const HSK4_DATA = {"lessons": [{"id": 1,"title_cn": "我们来中国学习了","title_pinyin": "","title_vn": "Chúng em đã đến Trung Quốc học tập","goals": ["Có thể nghe hiểu và trao đổi thông tin về làm thủ tục nhập học và xin học bổng.","Có thể trình bày bằng lời hoặc bằng văn bản lý do chọn chuyên ngành và định hướng phát triển nghề nghiệp trong tương lai.","Hiểu được tình hình học tập và sinh hoạt của du học sinh nước ngoài tại các trường đại học Trung Quốc."],"vocab": [{"hanzi": "签证","pinyin": "qiānzhèng","pos": "dt.","vn": "thị thực, visa"},{"hanzi": "入学","pinyin": "rùxué","pos": "dgt.","vn": "nhập học"},{"hanzi": "通知","pinyin": "tōngzhī","pos": "dgt./dt.","vn": "thông báo"},{"hanzi": "证件","pinyin": "zhèngjiàn","pos": "dt.","vn": "giấy tờ, giấy chứng nhận"},{"hanzi": "材料","pinyin": "cáiliào","pos": "dt.","vn": "tài liệu, tư liệu"},{"hanzi": "证","pinyin": "zhèng","pos": "dt.","vn": "giấy chứng nhận, chứng"},{"hanzi": "任何","pinyin": "rènhé","pos": "đt.","vn": "bất cứ, bất kỳ"},{"hanzi": "食堂","pinyin": "shítáng","pos": "dt.","vn": "nhà ăn, căng tin"},{"hanzi": "座","pinyin": "zuò","pos": "lượng.","vn": "(lượng từ dùng cho núi, tòa nhà và các vật thể cố định tương tự)"},{"hanzi": "申请","pinyin": "shēnqǐng","pos": "dgt.","vn": "xin, nộp đơn xin"},{"hanzi": "奖学金","pinyin": "jiǎngxuéjīn","pos": "dt.","vn": "học bổng"},{"hanzi": "表现","pinyin": "biǎoxiàn","pos": "dgt.","vn": "biểu hiện, thể hiện"},{"hanzi": "获得","pinyin": "huòdé","pos": "dgt.","vn": "giành được, đạt được"},{"hanzi": "要是","pinyin": "yàoshi","pos": "liên.","vn": "nếu, nếu như"},{"hanzi": "减轻","pinyin": "jiǎnqīng","pos": "dgt.","vn": "giảm nhẹ, giảm bớt"},{"hanzi": "经济","pinyin": "jīngjì","pos": "dt.","vn": "kinh tế"},{"hanzi": "压力","pinyin": "yālì","pos": "dt.","vn": "áp lực"},{"hanzi": "加油","pinyin": "jiāyóu","pos": "dgt.","vn": "cố gắng, cổ vũ"},{"hanzi": "随着","pinyin": "suízhe","pos": "giới.","vn": "cùng với"},{"hanzi": "课程","pinyin": "kèchéng","pos": "dt.","vn": "khóa học, chương trình học"},{"hanzi": "专业","pinyin": "zhuānyè","pos": "dt./tt.","vn": "chuyên ngành; chuyên nghiệp"},{"hanzi": "本科","pinyin": "běnkē","pos": "dt.","vn": "đại học (hệ cử nhân), bậc cử nhân"},{"hanzi": "硕士","pinyin": "shuòshì","pos": "dt.","vn": "thạc sĩ"},{"hanzi": "研究生","pinyin": "yánjiūshēng","pos": "dt.","vn": "nghiên cứu sinh, học viên cao học"},{"hanzi": "博士","pinyin": "bóshì","pos": "dt.","vn": "tiến sĩ"},{"hanzi": "研究","pinyin": "yánjiū","pos": "dgt.","vn": "nghiên cứu"},{"hanzi": "活动","pinyin": "huódòng","pos": "dt./dgt.","vn": "hoạt động"},{"hanzi": "通过","pinyin": "tōngguò","pos": "giới./dgt.","vn": "thông qua"},{"hanzi": "交流","pinyin": "jiāoliú","pos": "dgt.","vn": "giao lưu"},{"hanzi": "适应","pinyin": "shìyìng","pos": "dgt.","vn": "thích nghi, thích ứng"},{"hanzi": "将来","pinyin": "jiānglái","pos": "dt.","vn": "tương lai"},{"hanzi": "国际","pinyin": "guójì","pos": "tt./dt.","vn": "quốc tế"},{"hanzi": "当","pinyin": "dāng","pos": "dgt.","vn": "làm (nghề gì)"},{"hanzi": "教育","pinyin": "jiàoyù","pos": "dt./dgt.","vn": "giáo dục"},{"hanzi": "成为","pinyin": "chéngwéi","pos": "dgt.","vn": "trở thành"},{"hanzi": "教师","pinyin": "jiàoshī","pos": "dt.","vn": "giáo viên"},{"hanzi": "贸易","pinyin": "màoyì","pos": "dt.","vn": "thương mại, mậu dịch"},{"hanzi": "方面","pinyin": "fāngmiàn","pos": "dt.","vn": "phương diện, mặt"},{"hanzi": "知识","pinyin": "zhīshi","pos": "dt.","vn": "kiến thức"},{"hanzi": "另","pinyin": "lìng","pos": "đt.","vn": "khác, cái khác"}],"grammar": [{"title": "指示代词\"任何\"","explanation_vn": "Đại từ chỉ định \"任何\" biểu thị ý nghĩa \"bất cứ cái gì\". Khi bổ nghĩa cho danh từ thường không dùng \"的\", phía sau thường đi kèm với \"都\" hoặc \"也\".","examples": [{"cn": "你们以后有任何问题都可以来找我。","pinyin": "","vn": "Sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô."},{"cn": "明天我们8点出发，任何人也不能迟到。","pinyin": "","vn": "Ngày mai chúng ta xuất phát lúc 8 giờ, bất cứ ai cũng không được đến muộn."},{"cn": "学校有任何通知，我都会第一时间告诉你。","pinyin": "","vn": "Trường có bất cứ thông báo gì, mình đều sẽ báo cho cậu ngay lập tức."}]},{"title": "假设复句\"要是……，就……\"","explanation_vn": "Vế trước nêu ra một giả thiết, vế sau biểu thị kết quả xảy ra khi giả thiết đó được thực hiện.","examples": [{"cn": "要是申请到奖学金，就能减轻不少经济压力。","pinyin": "","vn": "Nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế."},{"cn": "你要是明天有时间，就跟我一起去爬山吧。","pinyin": "","vn": "Nếu ngày mai cậu có thời gian thì cùng mình đi leo núi nhé."},{"cn": "要是她不愿意参加比赛，我们就再问问别人。","pinyin": "","vn": "Nếu cô ấy không muốn tham gia thi đấu thì chúng ta sẽ hỏi người khác."}]},{"title": "介词\"随着\"","explanation_vn": "Giới từ \"随着\" thường đi kèm với từ ngữ hoặc cụm từ biểu thị sự thay đổi, biểu thị một sự việc là điều kiện để sự việc khác xảy ra.","examples": [{"cn": "随着中国的发展，越来越多的外国学生来到中国的大学学习。","pinyin": "","vn": "Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập."},{"cn": "随着中文水平的提高，我现在能看懂中文报纸了。","pinyin": "","vn": "Cùng với trình độ tiếng Trung được nâng cao, bây giờ mình đã có thể đọc hiểu báo tiếng Trung."},{"cn": "随着小区的环境越来越好，来这里买房子的人也变多了。","pinyin": "","vn": "Cùng với môi trường khu dân cư ngày càng tốt lên, số người đến đây mua nhà cũng tăng lên."}]},{"title": "并列复句\"一方面……，另一方面……\"","explanation_vn": "Câu phức liên hợp \"一方面……，另一方面……\" thường dùng để trình bày hai phương diện nguyên nhân, tình huống,... cùng tồn tại song song.","examples": [{"cn": "来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin": "","vn": "Đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này."},{"cn": "他经常在网上买东西，一方面因为便宜，另一方面因为方便。","pinyin": "","vn": "Anh ấy thường mua đồ trên mạng, một mặt vì rẻ, mặt khác vì tiện lợi."},{"cn": "多做运动一方面能让身体更健康，另一方面也能减轻压力。","pinyin": "","vn": "Tập thể dục nhiều một mặt có thể giúp cơ thể khỏe mạnh hơn, mặt khác cũng có thể giảm bớt áp lực."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "老师","cn": "你们好，欢迎来到中国留学！请把护照、签证和入学通知书给我。","pinyin": ""},{"speaker": "白家月","cn": "好的。这是我们的证件和材料。","pinyin": ""},{"speaker": "","cn": "（几分钟后。）","pinyin": ""},{"speaker": "老师","cn": "办好了，这是你们的学生证，下周一开始上课。先试听两周，然后在网上选课。","pinyin": ""},{"speaker": "白家月、陈天中","cn": "谢谢老师。","pinyin": ""},{"speaker": "老师","cn": "不客气，你们以后有任何问题都可以来找我。","pinyin": ""}],"translation_vn": "Cô giáo: Các em chào, chào mừng các em đến Trung Quốc du học! Hãy đưa hộ chiếu, visa và giấy báo nhập học cho cô.\nBạch Gia Nguyệt: Vâng ạ. Đây là giấy tờ và tài liệu của chúng em.\n(Vài phút sau.)\nCô giáo: Xong rồi, đây là thẻ sinh viên của các em, thứ Hai tuần sau bắt đầu học. Trước tiên dự thính hai tuần, sau đó chọn môn học trên mạng.\nBạch Gia Nguyệt, Trần Thiên Trung: Chúng em cảm ơn cô ạ.\nCô giáo: Không có gì, sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô.","audio_dialogue": "1-1.mp3","audio_vocab": "1-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "陈天中","cn": "你看，咱们的校园真大！有图书馆、体育馆、超市，还有好几个食堂。","pinyin": ""},{"speaker": "白家月","cn": "是啊，我觉得学校就像一座小城市，什么都有，方便极了。","pinyin": ""},{"speaker": "陈天中","cn": "刚才老师说，咱们可以申请奖学金，你了解过吗？","pinyin": ""},{"speaker": "白家月","cn": "我听说过一点儿，好像成绩好、表现好的学生都有机会获得奖学金。","pinyin": ""},{"speaker": "陈天中","cn": "那太好了，要是申请到奖学金，就能减轻不少经济压力。","pinyin": ""},{"speaker": "白家月","cn": "没错，我们一起加油吧！","pinyin": ""}],"translation_vn": "Trần Thiên Trung: Cậu xem, khuôn viên trường mình thật rộng! Có thư viện, nhà thi đấu, siêu thị, còn có mấy nhà ăn nữa.\nBạch Gia Nguyệt: Đúng vậy, mình thấy trường học giống như một thành phố nhỏ, cái gì cũng có, tiện lợi vô cùng.\nTrần Thiên Trung: Vừa nãy thầy/cô nói, chúng mình có thể xin học bổng, cậu tìm hiểu chưa?\nBạch Gia Nguyệt: Mình nghe nói một chút, hình như sinh viên có thành tích tốt, biểu hiện tốt đều có cơ hội giành được học bổng.\nTrần Thiên Trung: Thế thì tốt quá, nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế.\nBạch Gia Nguyệt: Đúng vậy, chúng mình cùng cố gắng nhé!","audio_dialogue": "1-3.mp3","audio_vocab": "1-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "随着中国的发展，越来越多的外国学生来到中国的大学学习。他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。除了读本科课程，他们还可以申请读硕士研究生或者博士研究生。在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。通过这些交流，外国学生能更快地适应中国的大学生活。","pinyin": ""}],"translation_vn": "Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập. Họ có thể học một năm khóa tiếng Trung trước, sau đó căn cứ vào sở thích và nhu cầu của bản thân để chọn chuyên ngành. Ngoài việc học chương trình đại học, họ còn có thể xin học thạc sĩ hoặc tiến sĩ. Ở trường đại học, du học sinh nước ngoài có thể cùng học tập, nghiên cứu, tham gia các hoạt động trong khuôn viên trường với sinh viên Trung Quốc. Thông qua những giao lưu này, du học sinh nước ngoài có thể nhanh chóng thích nghi với cuộc sống đại học ở Trung Quốc.","audio_dialogue": "1-5.mp3","audio_vocab": "1-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "很多外国学生来中国学习以前，就已经想好了自己的发展方向。有人对经济感兴趣，希望将来在国际公司工作；有人喜欢学医，打算回国后当一名医生；还有人对教育有热情，想要成为一名教师。陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。安妮以后想做一名中文老师，所以要选择国际中文教育专业。对他们来说，来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin": ""}],"translation_vn": "Rất nhiều du học sinh nước ngoài trước khi đến Trung Quốc học tập đã nghĩ kỹ về hướng phát triển của bản thân. Có người hứng thú với kinh tế, hy vọng sau này làm việc trong công ty quốc tế; có người thích học y, dự định về nước làm bác sĩ; lại có người nhiệt huyết với giáo dục, muốn trở thành giáo viên. Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học để hiểu biết thêm về lĩnh vực thương mại quốc tế. Annie sau này muốn làm giáo viên tiếng Trung, vì vậy sẽ chọn chuyên ngành Giáo dục tiếng Trung quốc tế. Đối với họ, đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này.","audio_dialogue": "1-7.mp3","audio_vocab": "1-8.mp3"}]},{"id": 2,"title_cn": "租到了合适的房子","title_pinyin": "","title_vn": "Tôi đã thuê được căn nhà phù hợp","goals": ["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến việc thuê nhà.","Có thể trình bày bằng lời hoặc bằng văn bản nguyện vọng, yêu cầu thuê nhà,...","Hiểu được quan niệm về nhà ở của người Trung Quốc."],"vocab": [{"hanzi": "房东","pinyin": "fángdōng","pos": "dt.","vn": "chủ nhà"},{"hanzi": "出租","pinyin": "chūzū","pos": "dgt.","vn": "cho thuê"},{"hanzi": "房租","pinyin": "fángzū","pos": "dt.","vn": "tiền thuê nhà"},{"hanzi": "收拾","pinyin": "shōushi","pos": "dgt.","vn": "dọn dẹp, thu dọn"},{"hanzi": "租","pinyin": "zū","pos": "dgt.","vn": "thuê"},{"hanzi": "嗯","pinyin": "ng","pos": "ct.","vn": "ừ, vâng"},{"hanzi": "亮","pinyin": "liàng","pos": "tt./dgt.","vn": "sáng, sáng sủa"},{"hanzi": "就是","pinyin": "jiùshì","pos": "trợ.","vn": "(trợ từ dùng cuối câu, thường đi với \"了\" để nhấn mạnh sự khẳng định) là được, thế thôi"},{"hanzi": "种","pinyin": "zhòng","pos": "dgt.","vn": "trồng"},{"hanzi": "周围","pinyin": "zhōuwéi","pos": "dt.","vn": "xung quanh"},{"hanzi": "不过","pinyin": "búguò","pos": "liên.","vn": "nhưng, tuy nhiên"},{"hanzi": "毕业","pinyin": "bìyè","pos": "dgt.","vn": "tốt nghiệp"},{"hanzi": "恐怕","pinyin": "kǒngpà","pos": "phó.","vn": "e rằng, sợ rằng"},{"hanzi": "热闹","pinyin": "rènao","pos": "dgt./tt./dt.","vn": "náo nhiệt, nhộn nhịp; sự náo nhiệt"},{"hanzi": "入住","pinyin": "rùzhù","pos": "dgt.","vn": "chuyển vào ở, nhận phòng"},{"hanzi": "日记","pinyin": "rìjì","pos": "dt.","vn": "nhật ký"},{"hanzi": "顺利","pinyin": "shùnlì","pos": "tt.","vn": "thuận lợi, suôn sẻ"},{"hanzi": "并","pinyin": "bìng","pos": "liên./phó.","vn": "và, hơn nữa; (nhấn mạnh phủ định) hoàn toàn (không)"},{"hanzi": "客厅","pinyin": "kètīng","pos": "dt.","vn": "phòng khách"},{"hanzi": "台","pinyin": "tái","pos": "lượng.","vn": "(lượng từ dùng cho máy móc, thiết bị,...)"},{"hanzi": "厨房","pinyin": "chúfáng","pos": "dt.","vn": "nhà bếp"},{"hanzi": "平常","pinyin": "píngcháng","pos": "dt./tt.","vn": "ngày thường; bình thường"},{"hanzi": "基本上","pinyin": "jīběnshàng","pos": "phó.","vn": "về cơ bản, về căn bản"},{"hanzi": "整个","pinyin": "zhěnggè","pos": "tt.","vn": "cả, toàn bộ"},{"hanzi": "毛巾","pinyin": "máojīn","pos": "dt.","vn": "khăn mặt"},{"hanzi": "建议","pinyin": "jiànyì","pos": "dt./dgt.","vn": "đề nghị, gợi ý"},{"hanzi": "查看","pinyin": "chákàn","pos": "dgt.","vn": "xem xét, kiểm tra"},{"hanzi": "信息","pinyin": "xìnxī","pos": "dt.","vn": "thông tin"},{"hanzi": "查找","pinyin": "cházhǎo","pos": "dgt.","vn": "tìm kiếm"},{"hanzi": "接着","pinyin": "jiēzhe","pos": "phó./dgt.","vn": "tiếp theo, sau đó"},{"hanzi": "同时","pinyin": "tóngshí","pos": "liên./dt.","vn": "đồng thời"},{"hanzi": "位置","pinyin": "wèizhì","pos": "dt.","vn": "vị trí"},{"hanzi": "价格","pinyin": "jiàgé","pos": "dt.","vn": "giá cả"},{"hanzi": "理想","pinyin": "lǐxiǎng","pos": "tt./dt.","vn": "lý tưởng"},{"hanzi": "由于","pinyin": "yóuyú","pos": "liên./giới.","vn": "do, bởi vì"},{"hanzi": "工资","pinyin": "gōngzī","pos": "dt.","vn": "tiền lương"},{"hanzi": "感","pinyin": "gǎn","pos": "htố.","vn": "(hậu tố chỉ cảm giác) cảm"}],"grammar": [{"title": "固定格式\"×就是了\"","explanation_vn": "Cấu trúc cố định \"×就是了\" được dùng trong khẩu ngữ, đặt ở cuối câu để biểu thị ý khẳng định.","examples": [{"cn": "如果决定租了，告诉我就是了。","pinyin": "","vn": "Nếu quyết định thuê rồi thì báo cho tôi là được."},{"cn": "我一定能办到，您放心就是了。","pinyin": "","vn": "Tôi chắc chắn làm được, ông/bà cứ yên tâm."},{"cn": "这次考得不好没关系，下次努力就是了。","pinyin": "","vn": "Lần này thi không tốt cũng không sao, lần sau cố gắng là được."}]},{"title": "转折复句\"……，不过……\"","explanation_vn": "Liên từ \"不过\" được dùng ở đầu vế câu thứ hai trong hai vế câu, biểu thị ý chuyển ngoặt.","examples": [{"cn": "这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。","pinyin": "","vn": "Môi trường khu dân cư này thật sự không tệ, nhưng tôi nghe nói gần đó có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây."},{"cn": "我们在动物园看见了很多动物，不过没看见大熊猫。","pinyin": "","vn": "Chúng tôi đã nhìn thấy rất nhiều động vật ở sở thú, nhưng không nhìn thấy gấu trúc."},{"cn": "我刚来北京时还不太习惯这里的天气，不过很快就适应了。","pinyin": "","vn": "Khi mới đến Bắc Kinh tôi vẫn chưa quen lắm với thời tiết ở đây, nhưng rất nhanh đã thích nghi được."}]},{"title": "连词/副词\"并\"","explanation_vn": "\"并\" có nhiều cách dùng. Phần này giới thiệu hai cách dùng của \"并\" là liên từ và phó từ: (1) \"并\" làm liên từ, nối các động từ song âm tiết, cụm từ hoặc vế câu song song, biểu thị quan hệ song song, mang ý nghĩa tiến thêm một bước; (2) \"并\" làm phó từ, đặt trước từ phủ định để nhấn mạnh ngữ khí phủ định, nói rõ sự thật không phải như vậy.","examples": [{"cn": "房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin": "","vn": "Chủ nhà lại giới thiệu cho tôi một lượt về đồ đạc trong nhà, đồng thời cho tôi biết cách sử dụng những thứ đó."},{"cn": "她考上了北京大学并申请到了奖学金。","pinyin": "","vn": "Cô ấy thi đỗ vào Đại học Bắc Kinh và xin được học bổng."},{"cn": "我并没有答应你就租这个房子，我还要再想想。","pinyin": "","vn": "Tôi hoàn toàn chưa đồng ý thuê căn nhà này, tôi còn phải suy nghĩ thêm."}]},{"title": "连词/介词\"由于\"","explanation_vn": "\"由于\" có hai cách dùng: (1) làm liên từ, đặt ở đầu vế câu trước trong câu phức để biểu thị nguyên nhân, vế câu sau thường có các từ như \"所以\", \"因此\"; (2) làm giới từ, biểu thị nguyên nhân hoặc lý do.","examples": [{"cn": "在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","pinyin": "","vn": "Ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà."},{"cn": "由于一直下大雨，所以我们决定不爬山了。","pinyin": "","vn": "Do trời mưa to liên tục, nên chúng tôi quyết định không leo núi nữa."},{"cn": "由于大家的努力，这次运动会我们班获得了第一名。","pinyin": "","vn": "Nhờ sự nỗ lực của mọi người, trong hội thao lần này lớp chúng tôi đã giành giải nhất."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "房东","cn": "请进！我给你们介绍一下，这个房子有两个房间，那个大房间出租，房租每月5500元。现在已经收拾好了，想租的话，今天就可以搬进来。","pinyin": ""},{"speaker": "白家月","cn": "嗯，这个房间真不小，还挺亮。小区离我们学校也不远。","pinyin": ""},{"speaker": "房东","cn": "是的，我们小区离地铁站也很近，生活上很方便。如果决定租了，告诉我就是了。","pinyin": ""},{"speaker": "白家月","cn": "好的，我们再去看看外边的环境。","pinyin": ""}],"translation_vn": "Chủ nhà: Mời vào! Để tôi giới thiệu cho các em, căn nhà này có hai phòng, phòng lớn kia cho thuê, tiền thuê mỗi tháng 5500 tệ. Hiện tại đã dọn dẹp xong rồi, nếu muốn thuê thì hôm nay có thể dọn vào ở luôn.\nBạch Gia Nguyệt: Dạ, phòng này thật sự không nhỏ, lại khá sáng sủa. Khu này cũng không xa trường của chúng em.\nChủ nhà: Đúng vậy, khu chúng tôi cũng gần ga tàu điện ngầm, sinh hoạt rất tiện lợi. Nếu quyết định thuê thì cứ báo cho tôi là được.\nBạch Gia Nguyệt: Vâng ạ, chúng em đi xem thêm môi trường bên ngoài nữa.","audio_dialogue": "2-1.mp3","audio_vocab": "2-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "李文","cn": "家月，你看，那边还有个小花园。","pinyin": ""},{"speaker": "白家月","cn": "嗯，这个小区到处是花，还种了不少树，周围也很安静。","pinyin": ""},{"speaker": "李文","cn": "是啊！这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。","pinyin": ""},{"speaker": "白家月","cn": "没关系，我还想多认识一些朋友，和他们一起玩呢。","pinyin": ""},{"speaker": "李文","cn": "是呢，大家可以一起热闹热闹。","pinyin": ""},{"speaker": "白家月","cn": "这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。","pinyin": ""}],"translation_vn": "Lý Văn: Gia Nguyệt, cậu xem, bên kia còn có một vườn hoa nhỏ nữa.\nBạch Gia Nguyệt: Ừ, khu này chỗ nào cũng có hoa, còn trồng khá nhiều cây, xung quanh cũng rất yên tĩnh.\nLý Văn: Đúng vậy! Môi trường khu này thật sự không tệ, nhưng mình nghe nói gần đây có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây. Cuối tuần họ có thể chơi đến khuya, e rằng sẽ ảnh hưởng đến việc nghỉ ngơi của cậu.\nBạch Gia Nguyệt: Không sao, mình còn muốn quen thêm vài người bạn, chơi cùng họ nữa.\nLý Văn: Đúng vậy, mọi người có thể cùng nhau vui vẻ náo nhiệt.\nBạch Gia Nguyệt: Ở đây tiền thuê hợp lý, môi trường tốt, hơn nữa chủ nhà cũng nhiệt tình, nên mình quyết định thuê căn nhà này rồi, ngày mai sẽ dọn vào nhà mới.","audio_dialogue": "2-3.mp3","audio_vocab": "2-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "8月25日，晴\n昨天我顺利租到了合适的房子，今天李文帮我搬家。搬进去的时候，房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。\n我看了一下，客厅里有椅子、沙发，还有一台大电视；厨房里有冰箱和一些做饭用的东西，不过，我平常主要在学校食堂吃，基本上不做饭。我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。\n看完整个房子后，我准备再去买几条毛巾，其他东西还不需要。","pinyin": ""}],"translation_vn": "Ngày 25 tháng 8, trời nắng\nHôm qua mình đã thuận lợi thuê được căn nhà ưng ý, hôm nay Lý Văn giúp mình chuyển nhà. Lúc dọn vào, chủ nhà lại giới thiệu cho mình một lượt về đồ đạc trong nhà, đồng thời cho mình biết cách sử dụng những thứ đó.\nMình xem qua một lượt, phòng khách có ghế, sofa, còn có một chiếc ti vi lớn; nhà bếp có tủ lạnh và một số đồ dùng để nấu ăn, nhưng mình thường chủ yếu ăn ở nhà ăn trường, về cơ bản không nấu ăn. Phòng mình thuê, ngoài một chiếc giường ra, còn có một chiếc điều hòa, một chiếc bàn học và một chiếc ghế.\nSau khi xem xong cả căn nhà, mình định đi mua thêm vài chiếc khăn mặt nữa, những thứ khác thì chưa cần.","audio_dialogue": "2-5.mp3","audio_vocab": "2-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "在李文的帮助下，白家月租到了合适的房子。对白家月来说，这次租房并不容易。根据李文的建议，她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。她看了好几个房子，才找到一个位置、环境和价格都合适的，最后顺利租到了理想的房子。\n租房的时候，李文告诉白家月，在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。","pinyin": ""}],"translation_vn": "Với sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà ưng ý. Đối với Bạch Gia Nguyệt mà nói, lần thuê nhà này không hề dễ dàng. Theo gợi ý của Lý Văn, trước tiên cô xem thông tin liên quan trên các trang web và ứng dụng cho thuê nhà, tìm kiếm căn nhà phù hợp, sau đó lại đi xem nhà, đồng thời tìm hiểu môi trường xung quanh căn nhà. Cô đã xem qua mấy căn nhà mới tìm được một căn có vị trí, môi trường và giá cả đều phù hợp, cuối cùng thuận lợi thuê được căn nhà lý tưởng.\nLúc thuê nhà, Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà. Sau khi đi làm vài năm, không ít người sẽ mua nhà, vì mọi người đều cho rằng có nhà mới có tổ ấm, có nhà riêng sẽ cảm thấy an toàn hơn.","audio_dialogue": "2-7.mp3","audio_vocab": "2-8.mp3"}]},{"id": 3,"title_cn": "手机扫一下","title_pinyin": "","title_vn": "Quét điện thoại một chút","goals": ["Có thể nghe hiểu và trao đổi về các chủ đề như tải ứng dụng, mua sắm trực tuyến, thanh toán bằng điện thoại.","Có thể diễn đạt bằng lời nói hoặc chữ viết các công dụng khác nhau của điện thoại di động.","Hiểu được các cách bảo vệ thông tin cá nhân trong thời đại mạng internet."],"vocab": [{"hanzi": "十字路口","pinyin": "shízì lùkǒu","pos": "","vn": "ngã tư"},{"hanzi": "直接","pinyin": "zhíjiē","pos": "tt.","vn": "trực tiếp"},{"hanzi": "转","pinyin": "zhuǎn","pos": "dgt.","vn": "rẽ, quay, chuyển"},{"hanzi": "正好","pinyin": "zhènghǎo","pos": "phó./tt.","vn": "đúng lúc, vừa khéo, vừa vặn"},{"hanzi": "熟悉","pinyin": "shúxī","pos": "dgt.","vn": "quen thuộc, am hiểu"},{"hanzi": "正","pinyin": "zhèng","pos": "tt.","vn": "thẳng, ngay ngắn"},{"hanzi": "目的地","pinyin": "mùdìdì","pos": "dt.","vn": "điểm đến, đích đến"},{"hanzi": "下载","pinyin": "xiàzài","pos": "dgt.","vn": "tải xuống"},{"hanzi": "进行","pinyin": "jìnxíng","pos": "dgt.","vn": "tiến hành, thực hiện"},{"hanzi": "支付","pinyin": "zhīfù","pos": "dgt.","vn": "thanh toán, chi trả"},{"hanzi": "软件","pinyin": "ruǎnjiàn","pos": "dt.","vn": "phần mềm"},{"hanzi": "不仅","pinyin": "bùjǐn","pos": "liên.","vn": "không những...(mà còn...)"},{"hanzi": "扫码","pinyin": "sǎomǎ","pos": "dgt.","vn": "quét mã QR"},{"hanzi": "结账","pinyin": "jiézhàng","pos": "dgt.","vn": "thanh toán, tính tiền"},{"hanzi": "购物","pinyin": "gòuwù","pos": "dgt.","vn": "mua sắm"},{"hanzi": "订","pinyin": "dìng","pos": "dgt.","vn": "đặt (hàng, chỗ)"},{"hanzi": "快递","pinyin": "kuàidì","pos": "dt.","vn": "chuyển phát nhanh"},{"hanzi": "微信","pinyin": "Wēixìn","pos": "danh từ riêng","vn": "WeChat"},{"hanzi": "支付宝","pinyin": "Zhīfùbǎo","pos": "danh từ riêng","vn": "Alipay"},{"hanzi": "现金","pinyin": "xiànjīn","pos": "dt.","vn": "tiền mặt"},{"hanzi": "网购","pinyin": "wǎnggòu","pos": "dgt.","vn": "mua sắm trực tuyến"},{"hanzi": "寄","pinyin": "jì","pos": "dgt.","vn": "gửi"},{"hanzi": "等","pinyin": "děng","pos": "trợ.","vn": "v.v., vân vân"},{"hanzi": "货","pinyin": "huò","pos": "dt.","vn": "hàng hóa"},{"hanzi": "甚至","pinyin": "shènzhì","pos": "liên.","vn": "thậm chí"},{"hanzi": "改变","pinyin": "gǎibiàn","pos": "dgt.","vn": "thay đổi"},{"hanzi": "手指","pinyin": "shǒuzhǐ","pos": "dt.","vn": "ngón tay"},{"hanzi": "乱","pinyin": "luàn","pos": "phó./tt.","vn": "bừa bãi, lộn xộn"},{"hanzi": "管","pinyin": "guǎn","pos": "dgt.","vn": "quản lý, kiểm soát"},{"hanzi": "提供","pinyin": "tígōng","pos": "dgt.","vn": "cung cấp"},{"hanzi": "身份证","pinyin": "shēnfènzhèng","pos": "dt.","vn": "chứng minh thư, thẻ căn cước"},{"hanzi": "个人","pinyin": "gèrén","pos": "dt.","vn": "cá nhân"},{"hanzi": "能否","pinyin": "néngfǒu","pos": "dgt.","vn": "có thể hay không"},{"hanzi": "保护","pinyin": "bǎohù","pos": "dgt.","vn": "bảo vệ"},{"hanzi": "于是","pinyin": "yúshì","pos": "liên.","vn": "thế là, vì vậy"},{"hanzi": "密码","pinyin": "mìmǎ","pos": "dt.","vn": "mật khẩu"},{"hanzi": "随便","pinyin": "suíbiàn","pos": "tt./dgt./liên.","vn": "tùy tiện, tùy ý"},{"hanzi": "技术","pinyin": "jìshù","pos": "dt.","vn": "kỹ thuật, công nghệ"},{"hanzi": "法律","pinyin": "fǎlǜ","pos": "dt.","vn": "pháp luật"},{"hanzi": "手段","pinyin": "shǒuduàn","pos": "dt.","vn": "biện pháp, thủ đoạn"},{"hanzi": "保证","pinyin": "bǎozhèng","pos": "dgt./dt.","vn": "đảm bảo, cam đoan"},{"hanzi": "网络","pinyin": "wǎngluò","pos": "dt.","vn": "mạng, internet"}],"grammar": [{"title": "转折复句\"……X是X，就是/不过……\"","explanation_vn": "Trong câu phức này, \"X是X\" là cấu trúc cố định, biểu thị sự khẳng định một tình huống hay thuộc tính nào đó, phía sau dùng các từ như \"就是\", \"不过\" để biểu thị ý chuyển ngoặt hoặc bổ sung thêm, chỉ ra rằng nội dung ở vế trước có giới hạn nhất định.","examples": [{"cn": "北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。","pinyin": "","vn": "Bắc Kinh rộng thì rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm."},{"cn": "这个房子便宜是便宜，就是离我的公司太远了。","pinyin": "","vn": "Căn nhà này rẻ thì rẻ thật, chỉ có điều là cách công ty tôi quá xa."},{"cn": "我们想是想了，就是没想出更好的办法。","pinyin": "","vn": "Chúng tôi nghĩ thì có nghĩ rồi, chỉ là chưa nghĩ ra cách nào tốt hơn."}]},{"title": "递进复句\"不仅/不光……，还/而且……\"","explanation_vn": "\"不仅/不光(không những)……，还/而且(mà còn)……\" biểu thị quan hệ tăng tiến. Vế sau là sự mở rộng hoặc bổ sung cho vế trước, biểu thị ý nghĩa tiến thêm một bước. Bài này học dạng câu phức có chung một chủ ngữ, cấu trúc là: Chủ ngữ + 不仅/不光……，还/而且……","examples": [{"cn": "现在我不仅会扫码结账，还会用手机在网上购物了。","pinyin": "","vn": "Bây giờ tôi không những biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa."},{"cn": "王老师不光教我们说中文，而且带我们了解中国文化。","pinyin": "","vn": "Cô Vương không những dạy chúng tôi nói tiếng Trung, mà còn dẫn chúng tôi tìm hiểu văn hóa Trung Quốc."},{"cn": "现在很多书店不仅卖书，还卖咖啡和奶茶。","pinyin": "","vn": "Hiện nay nhiều hiệu sách không những bán sách, mà còn bán cà phê và trà sữa."}]},{"title": "连词\"甚至\"","explanation_vn": "Liên từ \"甚至\" nhấn mạnh một tình huống nào đó nổi bật hơn, vượt ra ngoài dự đoán thông thường.","examples": [{"cn": "在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","pinyin": "","vn": "Mua sắm trực tuyến ở Trung Quốc không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"cn": "高铁速度真快，甚至还没看清楚，它就已经开过去了。","pinyin": "","vn": "Tàu cao tốc nhanh thật, thậm chí còn chưa kịp nhìn rõ thì nó đã chạy qua mất rồi."},{"cn": "这个小区真不错，有小花园、球场，甚至还有一个超市。","pinyin": "","vn": "Khu dân cư này thật tốt, có vườn hoa nhỏ, sân bóng, thậm chí còn có cả một siêu thị."}]},{"title": "承接复句\"……，于是……\"","explanation_vn": "Hai vế câu mô tả theo thứ tự các hành động hoặc sự việc liên tiếp, \"于是\" được dùng ở đầu vế sau. Giữa hai vế có quan hệ trước sau, về mặt logic có quan hệ nối tiếp.","examples": [{"cn": "在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心。","pinyin": "","vn": "Khi cung cấp những thông tin này, chúng ta cũng sẽ lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng."},{"cn": "她从小就想当医生，于是上大学时就选择了学医。","pinyin": "","vn": "Từ nhỏ cô ấy đã muốn làm bác sĩ, vì vậy khi lên đại học đã chọn học ngành y."},{"cn": "最近总感冒，于是他决定病好后就开始锻炼身体。","pinyin": "","vn": "Gần đây cứ bị cảm hoài, thế là anh ấy quyết định sau khi khỏi bệnh sẽ bắt đầu tập luyện thể thao."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "陈天中","cn": "请问，花园小区怎么走？","pinyin": ""},{"speaker": "同学","cn": "你往前走，到十字路口不要过马路，直接右转就到小区门口了。正好我也去那边，一起走吧。","pinyin": ""},{"speaker": "陈天中","cn": "好的。我刚来中国，不熟悉路。北京真是太大了。","pinyin": ""},{"speaker": "同学","cn": "北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。你也可以用手机地图，很容易就能找到目的地。","pinyin": ""},{"speaker": "陈天中","cn": "嗯，不过很多中文地名我还不认识。","pinyin": ""},{"speaker": "同学","cn": "没关系，你很快就会熟悉的。","pinyin": ""}],"translation_vn": "Trần Thiên Trung: Xin hỏi, đi đến khu dân cư Hoa Viên thế nào ạ?\nBạn học: Bạn đi thẳng về phía trước, đến ngã tư thì đừng qua đường, rẽ phải trực tiếp là đến cổng khu dân cư rồi. Đúng lúc mình cũng đi hướng đó, đi cùng nhau nhé.\nTrần Thiên Trung: Được ạ. Mình mới đến Trung Quốc, chưa quen đường. Bắc Kinh thật là quá rộng lớn.\nBạn học: Bắc Kinh thì rộng là rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm. Bạn cũng có thể dùng bản đồ điện thoại, rất dễ dàng tìm được điểm đến.\nTrần Thiên Trung: Vâng, nhưng có nhiều tên địa danh tiếng Trung mình vẫn chưa biết.\nBạn học: Không sao, bạn sẽ sớm quen thôi.","audio_dialogue": "3-1.mp3","audio_vocab": "3-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "陈天中","cn": "前两天和李文喝咖啡时，他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。","pinyin": ""},{"speaker": "白家月","cn": "他也教了我怎么用这两个软件。","pinyin": ""},{"speaker": "陈天中","cn": "现在我不仅会扫码结账，还会用手机在网上购物了。昨天我就在网上订了一台电脑，今天下午一点送到。","pinyin": ""},{"speaker": "白家月","cn": "学会了这些，我们在中国生活真是方便了不少。","pinyin": ""},{"speaker": "陈天中","cn": "对。快递员要到了，我得马上回去！家月，明天见！","pinyin": ""},{"speaker": "白家月","cn": "好的，天中，再见。","pinyin": ""}],"translation_vn": "Trần Thiên Trung: Hôm trước uống cà phê với Lý Văn, anh ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận biết chữ Hán trong đó, còn dạy mình dùng điện thoại để thanh toán.\nBạch Gia Nguyệt: Anh ấy cũng dạy mình cách dùng hai phần mềm này.\nTrần Thiên Trung: Bây giờ mình không chỉ biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa. Hôm qua mình đã đặt mua một chiếc máy tính trên mạng, chiều nay một giờ sẽ được giao đến.\nBạch Gia Nguyệt: Học được những điều này, cuộc sống của chúng ta ở Trung Quốc thật sự tiện lợi hơn nhiều.\nTrần Thiên Trung: Đúng vậy. Nhân viên giao hàng sắp đến rồi, mình phải về ngay đây! Gia Nguyệt, hẹn gặp lại ngày mai nhé!\nBạch Gia Nguyệt: Được rồi, Thiên Trung, tạm biệt.","audio_dialogue": "3-3.mp3","audio_vocab": "3-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "白家月和陈天中刚到北京时就发现，中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。在李文的帮助下，白家月和陈天中也都学会了用手机支付、网购、寄快递等等。在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。不过，由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。怎么才能管住自己不乱花钱呢？","pinyin": ""}],"translation_vn": "Khi Bạch Gia Nguyệt và Trần Thiên Trung mới đến Bắc Kinh đã phát hiện ra rằng người Trung Quốc khi thanh toán ở nhà hàng hay siêu thị hầu như đều dùng điện thoại để trả tiền, chỉ có họ là dùng tiền mặt để thanh toán. Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cũng đều đã học được cách thanh toán bằng điện thoại, mua sắm trực tuyến, gửi chuyển phát nhanh, v.v. Khi mua sắm trực tuyến ở Trung Quốc, không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình. Tuy nhiên, vì mua sắm trực tuyến quá tiện lợi, chỉ cần động ngón tay là có thể mua được thứ mình muốn, nên họ cũng bắt đầu lo lắng rằng mình sẽ tiêu tiền bừa bãi khi mua sắm trực tuyến. Làm thế nào để có thể kiểm soát bản thân không tiêu tiền bừa bãi đây?","audio_dialogue": "3-5.mp3","audio_vocab": "3-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "网上购物或者订票时，我们经常需要提供姓名、手机号、身份证号等个人信息。在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心，很快就有人给出了一些建议。比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……现在，很多国家也通过技术、法律等手段来保证个人信息安全。比如中国的网络安全法、个人信息保护法等就很好地保护了人们的个人信息。","pinyin": ""}],"translation_vn": "Khi mua sắm trực tuyến hoặc đặt vé, chúng ta thường cần cung cấp các thông tin cá nhân như họ tên, số điện thoại, số chứng minh thư. Khi cung cấp những thông tin này, chúng ta cũng lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng, và nhanh chóng có người đưa ra một số lời khuyên. Chẳng hạn, đừng tùy tiện nói mật khẩu cho người khác biết, không đăng thông tin vé tàu, vé máy bay của mình lên mạng... Hiện nay, rất nhiều quốc gia cũng thông qua các biện pháp như công nghệ, pháp luật để đảm bảo an toàn thông tin cá nhân. Ví dụ như Luật An ninh mạng, Luật Bảo vệ thông tin cá nhân của Trung Quốc đã bảo vệ rất tốt thông tin cá nhân của người dân.","audio_dialogue": "3-7.mp3","audio_vocab": "3-8.mp3"}]},{"id": 4,"title_cn": "很高兴能帮到你","title_pinyin": "","title_vn": "Rất vui vì đã giúp được bạn","goals": ["Có thể nghe hiểu và trao đổi về các chủ đề nhờ giúp đỡ hoặc giúp đỡ người khác trong cuộc sống hằng ngày.","Có thể diễn đạt bằng lời nói hoặc chữ viết về các phương thức đi lại khác nhau cùng ưu nhược điểm của chúng.","Hiểu được các dịch vụ tiện ích phục vụ người dân ở các thành phố Trung Quốc."],"vocab": [{"hanzi": "啊","pinyin": "ā","pos": "ct.","vn": "a, ôi (thán từ)"},{"hanzi": "停","pinyin": "tíng","pos": "dgt.","vn": "dừng; đỗ (xe)"},{"hanzi": "交","pinyin": "jiāo","pos": "dgt.","vn": "nộp, giao"},{"hanzi": "费","pinyin": "fèi","pos": "dt./dgt.","vn": "phí, chi phí; tốn kém"},{"hanzi": "信号","pinyin": "xìnhào","pos": "dt.","vn": "tín hiệu, sóng"},{"hanzi": "感谢","pinyin": "gǎnxiè","pos": "dgt.","vn": "cảm ơn"},{"hanzi": "联系","pinyin": "liánxì","pos": "dgt.","vn": "liên hệ"},{"hanzi": "方式","pinyin": "fāngshì","pos": "dt.","vn": "phương thức, cách thức"},{"hanzi": "客气","pinyin": "kèqi","pos": "dgt./tt.","vn": "khách sáo; lịch sự"},{"hanzi": "剩","pinyin": "shèng","pos": "dgt.","vn": "còn thừa, còn lại"},{"hanzi": "提","pinyin": "tí","pos": "dgt.","vn": "xách"},{"hanzi": "袋子","pinyin": "dàizi","pos": "dt.","vn": "túi"},{"hanzi": "重","pinyin": "zhòng","pos": "tt./dt.","vn": "nặng; trọng lượng"},{"hanzi": "算","pinyin": "suàn","pos": "dgt.","vn": "coi như, tính là"},{"hanzi": "再说","pinyin": "zàishuō","pos": "liên.","vn": "hơn nữa, vả lại"},{"hanzi": "之间","pinyin": "zhījiān","pos": "dt.","vn": "giữa, trong khoảng"},{"hanzi": "互相","pinyin": "hùxiāng","pos": "phó.","vn": "lẫn nhau, qua lại"},{"hanzi": "辛苦","pinyin": "xīnkǔ","pos": "dgt./tt.","vn": "vất vả, cực nhọc"},{"hanzi": "出行","pinyin": "chūxíng","pos": "dgt.","vn": "đi lại, ra ngoài đi đường"},{"hanzi": "距离","pinyin": "jùlí","pos": "dt./dgt.","vn": "khoảng cách; cách xa"},{"hanzi": "往往","pinyin": "wǎngwǎng","pos": "phó.","vn": "thường thường"},{"hanzi": "既","pinyin": "jì","pos": "phó.","vn": "vừa... (vừa...)"},{"hanzi": "电动车","pinyin": "diàndòngchē","pos": "dt.","vn": "xe điện"},{"hanzi": "速度","pinyin": "sùdù","pos": "dt.","vn": "tốc độ"},{"hanzi": "充电","pinyin": "chōngdiàn","pos": "dgt.","vn": "sạc điện"},{"hanzi": "流行","pinyin": "liúxíng","pos": "dgt.","vn": "phổ biến, thịnh hành"},{"hanzi": "省","pinyin": "shěng","pos": "dgt.","vn": "tiết kiệm"},{"hanzi": "力气","pinyin": "lìqi","pos": "dt.","vn": "sức lực"},{"hanzi": "乘客","pinyin": "chéngkè","pos": "dt.","vn": "hành khách"},{"hanzi": "购买","pinyin": "gòumǎi","pos": "dgt.","vn": "mua"},{"hanzi": "食物","pinyin": "shíwù","pos": "dt.","vn": "thức ăn"},{"hanzi": "免费","pinyin": "miǎnfèi","pos": "dgt.","vn": "miễn phí"},{"hanzi": "早餐","pinyin": "zǎocān","pos": "dt.","vn": "bữa sáng"},{"hanzi": "来得及","pinyin": "láidejí","pos": "dgt.","vn": "kịp, còn kịp"},{"hanzi": "鲜花","pinyin": "xiānhuā","pos": "dt.","vn": "hoa tươi"},{"hanzi": "顺便","pinyin": "shùnbiàn","pos": "phó.","vn": "tiện thể, nhân tiện"},{"hanzi": "心情","pinyin": "xīnqíng","pos": "dt.","vn": "tâm trạng"},{"hanzi": "更加","pinyin": "gèngjiā","pos": "phó.","vn": "càng, càng thêm"},{"hanzi": "愉快","pinyin": "yúkuài","pos": "tt.","vn": "vui vẻ"}],"grammar": [{"title": "可能补语\"动词+得/不+了\"","explanation_vn": "\"得了\" và \"不了\" được đặt sau động từ hoặc chen vào giữa từ ly hợp, tạo thành bổ ngữ khả năng, biểu thị động tác hay kết quả có thể hoàn thành hoặc thực hiện được hay không.","examples": [{"cn": "手机没有信号，上不了网，买不了地铁票了。","pinyin": "","vn": "Điện thoại không có sóng, không vào mạng được, nên không mua được vé tàu điện ngầm."},{"cn": "她刚才给我发信息，说她今天来不了了。","pinyin": "","vn": "Lúc nãy cô ấy nhắn tin cho tôi, nói hôm nay cô ấy không đến được."},{"cn": "明天的足球比赛，你们班男生参加得了吗？","pinyin": "","vn": "Trận bóng đá ngày mai, các bạn nam lớp bạn tham gia được không?"}]},{"title": "连词\"再说\"","explanation_vn": "Liên từ \"再说\" dùng để nêu ra một lý do hoặc tình huống, sau đó bổ sung thêm một lý do hoặc tình huống khác.","examples": [{"cn": "我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin": "","vn": "Tôi xách mấy thứ này coi như tập thể dục rồi, hơn nữa hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ."},{"cn": "今天太晚了，别去超市了，再说外面还在下雨呢。","pinyin": "","vn": "Hôm nay muộn quá rồi, đừng đi siêu thị nữa, với lại bên ngoài vẫn đang mưa đấy."},{"cn": "你就跟我们一起参加活动吧。你今天正好有时间，再说人多也更热闹。","pinyin": "","vn": "Bạn cứ tham gia hoạt động cùng chúng tôi đi. Hôm nay bạn đúng lúc rảnh, hơn nữa đông người thì càng náo nhiệt."}]},{"title": "并列复句\"既……，又/也……\"","explanation_vn": "\"既……，又/也……\" dùng để liên kết tính từ, động từ hoặc cụm từ, biểu thị việc đồng thời có mấy tính chất hoặc tồn tại mấy tình huống cùng lúc.","examples": [{"cn": "她觉得这样既方便，又能锻炼身体，还能保护环境。","pinyin": "","vn": "Cô ấy thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại còn bảo vệ được môi trường."},{"cn": "这家饭馆的菜既好吃，又便宜。","pinyin": "","vn": "Món ăn ở nhà hàng này vừa ngon, vừa rẻ."},{"cn": "我很喜欢这门课程，既能提高中文水平，也能学到历史知识。","pinyin": "","vn": "Tôi rất thích môn học này, vừa có thể nâng cao trình độ tiếng Trung, vừa có thể học được kiến thức lịch sử."}]},{"title": "固定短语\"来得及/来不及\"","explanation_vn": "\"来得及\" biểu thị vẫn còn thời gian, có thể lo liệu hoặc kịp làm; \"来不及\" biểu thị vì thời gian gấp gáp nên không thể lo liệu hoặc không kịp làm.","examples": [{"cn": "没来得及吃早饭的人在这里就能买到热包子和牛奶等。","pinyin": "","vn": "Những người chưa kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây."},{"cn": "你现在才告诉我，我来不及通知大家了。","pinyin": "","vn": "Bây giờ bạn mới nói cho tôi biết, tôi không kịp thông báo cho mọi người nữa rồi."},{"cn": "中午12点的飞机，咱们9点出发来得及吗？","pinyin": "","vn": "Chuyến bay 12 giờ trưa, chúng ta xuất phát lúc 9 giờ có kịp không?"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "陈天中","cn": "啊，我的手机停机了！怎么办啊？","pinyin": ""},{"speaker": "路人","cn": "你好，你看上去很着急，需要帮忙吗？","pinyin": ""},{"speaker": "陈天中","cn": "我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。","pinyin": ""},{"speaker": "路人","cn": "你要去哪儿？我帮你买张票。","pinyin": ""},{"speaker": "陈天中","cn": "太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。","pinyin": ""},{"speaker": "路人","cn": "别客气，很高兴能帮到你。","pinyin": ""}],"translation_vn": "Trần Thiên Trung: A, điện thoại của mình bị khóa máy rồi! Phải làm sao đây?\nNgười qua đường: Chào bạn, trông bạn có vẻ rất gấp, cần giúp đỡ không?\nTrần Thiên Trung: Mình quên đóng tiền điện thoại nên bị khóa máy rồi. Mình không mang tiền mặt, điện thoại lại không có sóng, không vào mạng được, không mua được vé tàu điện ngầm nữa.\nNgười qua đường: Bạn định đi đâu? Để mình mua vé giúp bạn.\nTrần Thiên Trung: Cảm ơn bạn nhiều lắm, mình muốn đến ga Đại học Bắc Kinh. Mà này, bạn có thể cho mình biết cách liên lạc với bạn không? Mình muốn trả lại tiền cho bạn.\nNgười qua đường: Đừng khách sáo, rất vui vì đã giúp được bạn.","audio_dialogue": "4-1.mp3","audio_vocab": "4-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "白家月","cn": "阿姨，您怎么站在这儿不上楼？","pinyin": ""},{"speaker": "邻居","cn": "我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。","pinyin": ""},{"speaker": "白家月","cn": "我正好要上楼，我帮您提上去吧。","pinyin": ""},{"speaker": "邻居","cn": "不用不用，这几个袋子太重了，我自己拿吧。","pinyin": ""},{"speaker": "白家月","cn": "没事，我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin": ""},{"speaker": "邻居","cn": "谢谢家月！那就辛苦你了。","pinyin": ""}],"translation_vn": "Bạch Gia Nguyệt: Cô ơi, sao cô đứng đây mà không lên nhà vậy ạ?\nHàng xóm: Cô lái xe đi siêu thị mua kha khá đồ, vừa mang một ít lên đây. Cô nghỉ một chút rồi quay lại xe lấy nốt phần còn lại.\nBạch Gia Nguyệt: Cháu đúng lúc cũng định lên nhà, để cháu xách giúp cô lên nhé.\nHàng xóm: Không cần đâu, mấy túi này nặng lắm, để cô tự xách thôi.\nBạch Gia Nguyệt: Không sao đâu cô, cháu xách mấy thứ này coi như tập thể dục rồi, với lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ ạ.\nHàng xóm: Cảm ơn Gia Nguyệt nhé! Vậy thì vất vả cho cháu rồi.","audio_dialogue": "4-3.mp3","audio_vocab": "4-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "在城市里，人们出行的方式越来越多。短距离出行时，骑自行车往往是人们常见的选择。白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。除了骑自行车，人们还会选择骑电动车。电动车速度快，价格不高，充电也很方便，所以越来越流行。陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。","pinyin": ""}],"translation_vn": "Trong thành phố, cách thức đi lại của mọi người ngày càng đa dạng. Khi di chuyển quãng đường ngắn, đi xe đạp thường là lựa chọn phổ biến của mọi người. Bạch Gia Nguyệt rất thích đạp xe đến trường, cô ấy cảm thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại vừa bảo vệ môi trường. Ngoài đi xe đạp ra, mọi người còn có thể chọn đi xe điện. Xe điện có tốc độ nhanh, giá cả không cao, sạc điện cũng rất tiện, nên ngày càng phổ biến. Trần Thiên Trung bình thường cũng đi xe đạp, nhưng để tiết kiệm sức lực, gần đây anh ấy định mua một chiếc xe điện.","audio_dialogue": "4-5.mp3","audio_vocab": "4-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "在中国，乘客可以在不少地铁站里直接扫码购买食物和饮料，有的地铁站还提供免费借雨伞、发雨衣等服务。有些地铁站附近公司比较多，工作日站里还有早餐车，没来得及吃早饭的人在这里就能买到热包子和牛奶等，省了不少时间。有的地铁站里甚至还有鲜花店，乘客下班时可以顺便买花送给家人。这些小小的服务，不仅方便了人们的出行，也让大家的心情变得更加愉快。","pinyin": ""}],"translation_vn": "Ở Trung Quốc, hành khách có thể quét mã trực tiếp để mua đồ ăn và thức uống ngay tại nhiều ga tàu điện ngầm, có ga còn cung cấp dịch vụ cho mượn ô miễn phí, phát áo mưa, v.v. Một số ga tàu điện ngầm gần nơi có nhiều công ty, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng, những người không kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây, tiết kiệm được không ít thời gian. Có ga tàu điện ngầm thậm chí còn có cả cửa hàng hoa tươi, hành khách khi tan làm có thể tiện thể mua hoa tặng người thân. Những dịch vụ nhỏ bé này, không những giúp việc đi lại của mọi người thuận tiện hơn, mà còn khiến tâm trạng của mọi người trở nên vui vẻ hơn.","audio_dialogue": "4-7.mp3","audio_vocab": "4-8.mp3"}]},{"id": 5,"title_cn": "“不怕辣”和“怕不辣”","title_pinyin": "","title_vn": "“Không sợ cay” và “sợ không cay”","goals": ["Có thể nghe hiểu và trao đổi về chủ đề thói quen ăn uống và tụ họp ăn uống.","Có thể diễn đạt bằng lời nói hoặc chữ viết về sở thích ăn uống cá nhân và trải nghiệm dùng bữa.","Hiểu được thói quen ăn uống của người Trung Quốc và lễ nghi sắp xếp chỗ ngồi trong các bữa tiệc chính thức."],"vocab": [{"hanzi": "至少","pinyin": "zhìshǎo","pos": "phó.","vn": "ít nhất"},{"hanzi": "中餐","pinyin": "zhōngcān","pos": "dt.","vn": "bữa ăn Trung Hoa, món Trung"},{"hanzi": "专门","pinyin": "zhuānmén","pos": "phó./tt.","vn": "chuyên, đặc biệt; chuyên biệt"},{"hanzi": "煮","pinyin": "zhŭ","pos": "dgt.","vn": "nấu, luộc"},{"hanzi": "油","pinyin": "yóu","pos": "dt.","vn": "dầu"},{"hanzi": "道","pinyin": "dào","pos": "lượng.","vn": "(lượng từ chỉ món ăn, công đoạn...)"},{"hanzi": "熟","pinyin": "shú/shóu","pos": "tt.","vn": "chín; quen thuộc"},{"hanzi": "倒","pinyin": "dào","pos": "dgt.","vn": "đổ, rót"},{"hanzi": "辣椒","pinyin": "làjiāo","pos": "dt.","vn": "ớt"},{"hanzi": "辣","pinyin": "là","pos": "tt.","vn": "cay"},{"hanzi": "水煮鱼","pinyin": "Shuǐzhǔyú","pos": "danh từ riêng","vn": "Cá om nước kiểu Tứ Xuyên (Thủy chử ngư)"},{"hanzi": "敢","pinyin": "gǎn","pos": "dgt.","vn": "dám"},{"hanzi": "肚子","pinyin": "dùzi","pos": "dt.","vn": "bụng"},{"hanzi": "相同","pinyin": "xiāngtóng","pos": "tt.","vn": "giống nhau"},{"hanzi": "顺序","pinyin": "shùnxù","pos": "dt.","vn": "thứ tự, trình tự"},{"hanzi": "够","pinyin": "gòu","pos": "phó./dgt.","vn": "khá, đủ mức; đủ"},{"hanzi": "不够","pinyin": "búgòu","pos": "phó./dgt.","vn": "không đủ"},{"hanzi": "达到","pinyin": "dádào","pos": "dgt.","vn": "đạt đến, đạt tới"},{"hanzi": "聚","pinyin": "jù","pos": "dgt.","vn": "tụ họp"},{"hanzi": "午餐","pinyin": "wǔcān","pos": "dt.","vn": "bữa trưa"},{"hanzi": "咸","pinyin": "xián","pos": "tt.","vn": "mặn"},{"hanzi": "凉","pinyin": "liáng","pos": "tt.","vn": "nguội, mát; (món) nguội"},{"hanzi": "酸","pinyin": "suān","pos": "tt.","vn": "chua"},{"hanzi": "汤","pinyin": "tāng","pos": "dt.","vn": "canh, súp"},{"hanzi": "各","pinyin": "gè","pos": "phó./đt.","vn": "mỗi, từng"},{"hanzi": "付","pinyin": "fù","pos": "dgt.","vn": "trả (tiền)"},{"hanzi": "聚餐","pinyin": "jùcān","pos": "dgt.","vn": "ăn tụ tập, liên hoan"},{"hanzi": "辣子鸡","pinyin": "Làzijī","pos": "danh từ riêng","vn": "Gà xào ớt (Lạt tử kê)"},{"hanzi": "松鼠鼟鱼","pinyin": "Sōngshǔ Guìyú","pos": "danh từ riêng","vn": "Cá quế hình sóc (Tùng thử quế ngư)"},{"hanzi": "红烧羊肉","pinyin": "Hóngshāo Yángròu","pos": "danh từ riêng","vn": "Thịt cừu kho đỏ"},{"hanzi": "贵州","pinyin": "Guìzhōu","pos": "danh từ riêng","vn": "tỉnh Quý Châu"},{"hanzi": "酸汤米线","pinyin": "Suāntāng Mǐxiàn","pos": "danh từ riêng","vn": "Bún nước chua"},{"hanzi": "随意","pinyin": "suíyì","pos": "tt.","vn": "tùy ý, thoải mái"},{"hanzi": "正式","pinyin": "zhèngshì","pos": "tt.","vn": "chính thức"},{"hanzi": "普通","pinyin": "pǔtōng","pos": "tt.","vn": "bình thường, phổ thông"},{"hanzi": "重视","pinyin": "zhòngshì","pos": "dgt.","vn": "coi trọng"},{"hanzi": "座位","pinyin": "zuòwèi","pos": "dt.","vn": "chỗ ngồi"},{"hanzi": "安排","pinyin": "ānpái","pos": "dgt.","vn": "sắp xếp"},{"hanzi": "按照","pinyin": "ànzhào","pos": "giới.","vn": "theo, dựa theo"},{"hanzi": "年龄","pinyin": "niánlíng","pos": "dt.","vn": "tuổi tác"},{"hanzi": "面对","pinyin": "miànduì","pos": "dgt.","vn": "đối diện"},{"hanzi": "主人","pinyin": "zhǔrén","pos": "dt.","vn": "chủ nhà"},{"hanzi": "等","pinyin": "děng","pos": "giới.","vn": "đợi đến, chờ đến"},{"hanzi": "尊重","pinyin": "zūnzhòng","pos": "dgt.","vn": "tôn trọng"}],"grammar": [{"title": "范围副词“至少” Phó từ chỉ phạm vi “至少”","explanation_vn": "Phó từ chỉ phạm vi \"至少\" biểu thị thời gian, số lượng, mức độ... không thấp hơn một giới hạn tối thiểu nào đó.","examples": [{"cn": "家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin": "","vn": "Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?"},{"cn": "每年至少有两百名留学生来我校学习中文专业。","pinyin": "","vn": "Mỗi năm có ít nhất hai trăm du học sinh đến trường chúng tôi học chuyên ngành tiếng Trung."},{"cn": "我们虽然没有见过面，但至少在网上聊过很多次，也算比较熟悉了。","pinyin": "","vn": "Tuy chúng tôi chưa gặp mặt nhau, nhưng ít nhất cũng đã trò chuyện trên mạng nhiều lần, cũng coi như khá quen biết rồi."}]},{"title": "副词/动词“够” Phó từ/Động từ “够”","explanation_vn": "\"够\" có hai từ loại: (1) phó từ, biểu thị mức độ cao, thường dùng trong cấu trúc cố định \"够……的\"; (2) động từ, biểu thị về số lượng đáp ứng đủ nhu cầu hoặc đạt đến một tiêu chuẩn, mức độ nào đó.","examples": [{"cn": "你的中文水平够高的，这都听懂了！","pinyin": "","vn": "Trình độ tiếng Trung của bạn khá cao đấy, cái này cũng nghe hiểu được!"},{"cn": "明天请家月和李文来家里吃饭，四个菜够不够？","pinyin": "","vn": "Ngày mai mời Gia Nguyệt và Lý Văn đến nhà ăn cơm, bốn món có đủ không?"},{"cn": "我尝了一下，还不够甸，再加一点儿糖吧。","pinyin": "","vn": "Tôi nếm thử rồi, vẫn chưa đủ ngọt, cho thêm chút đường nữa đi."}]},{"title": "固定格式“各×各的” Cấu trúc cố định “各×各的”","explanation_vn": "Cấu trúc cố định \"各×各的\" biểu thị mỗi người độc lập thực hiện cùng một loại hành động, không ảnh hưởng lẫn nhau.","examples": [{"cn": "大家觉得还是各付各的更合适。","pinyin": "","vn": "Mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn."},{"cn": "到了办公室，大家就开始各忙各的了。","pinyin": "","vn": "Đến văn phòng, mọi người liền bắt đầu ai làm việc của người nấy."},{"cn": "在图书馆里，大家都很安静，各看各的书。","pinyin": "","vn": "Trong thư viện, mọi người đều rất yên lặng, ai đọc sách của người nấy."}]},{"title": "介词“等” Giới từ “等”","explanation_vn": "Trong bài này, \"等\" là giới từ, biểu thị \"đợi đến\", dùng để dẫn ra thời gian, điều kiện.","examples": [{"cn": "如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin": "","vn": "Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi."},{"cn": "等我写完作业，再跟你出去玩。","pinyin": "","vn": "Đợi tôi làm xong bài tập rồi sẽ ra ngoài chơi với bạn."},{"cn": "等我们到火车站的时候，火车已经开走了。","pinyin": "","vn": "Đợi đến khi chúng tôi tới ga tàu thì tàu đã chạy mất rồi."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "刘明","cn": "家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin": ""},{"speaker": "白家月","cn": "习惯了，而且我很喜欢吃中国菜。","pinyin": ""},{"speaker": "王一雪","cn": "你还没吃过水煮鱼吧？这是我专门为你做的。","pinyin": ""},{"speaker": "白家月","cn": "看起来不像水煮鱼，更像“油煮鱼”。","pinyin": ""},{"speaker": "王一雪","cn": "这道菜是先用水把鱼煮熟，最后再倒上辣椒油，其实只有最上面那一层是油。你尝尝，对你来说辣不辣？","pinyin": ""},{"speaker": "白家月","cn": "辣是辣，但是非常好吃！","pinyin": ""},{"speaker": "王一雪","cn": "那你多吃点儿，不要客气。","pinyin": ""}],"translation_vn": "Lưu Minh: Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?\nBạch Gia Nguyệt: Quen rồi ạ, với lại em rất thích ăn món Trung Quốc.\nVương Nhất Tuyết: Em chưa ăn cá om kiểu Tứ Xuyên bao giờ đúng không? Đây là món chị làm riêng cho em đấy.\nBạch Gia Nguyệt: Trông không giống cá om nước, mà giống “cá om dầu” hơn.\nVương Nhất Tuyết: Món này là luộc chín cá bằng nước trước, cuối cùng mới đổ dầu ớt lên trên, thực ra chỉ có lớp trên cùng là dầu thôi. Em nếm thử xem, với em thì có cay không?\nBạch Gia Nguyệt: Cay thì cay thật, nhưng rất ngon!\nVương Nhất Tuyết: Vậy em ăn nhiều một chút, đừng khách sáo.","audio_dialogue": "5-1.mp3","audio_vocab": "5-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "我听李文说，你现在也爱吃辣了？","pinyin": ""},{"speaker": "白家月","cn": "是的，来中国以后，我越来越喜欢吃辣了。","pinyin": ""},{"speaker": "王一雪","cn": "我们以前不太敢吃辣，吃完可能会肚子不舒服，不过现在也慢慢适应了。","pinyin": ""},{"speaker": "刘明","cn": "对，我们现在都不怕辣了。家月，你是“不怕辣”还是“怕不辣”？","pinyin": ""},{"speaker": "白家月","cn": "中文真有意思，相同的字，顺序一换，意思就变了。","pinyin": ""},{"speaker": "李文","cn": "你的中文水平够高的，这都听懂了！你说得对，“不怕辣”是说不怕吃辣的菜，“怕不辣”是担心菜还不够辣呢。","pinyin": ""},{"speaker": "白家月","cn": "我还达不到“怕不辣”的水平，甚至也不能算“不怕辣”，只是喜欢吃辣。","pinyin": ""}],"translation_vn": "Vương Nhất Tuyết: Chị nghe Lý Văn nói, bây giờ em cũng thích ăn cay rồi à?\nBạch Gia Nguyệt: Vâng, sau khi đến Trung Quốc, em ngày càng thích ăn cay hơn.\nVương Nhất Tuyết: Trước đây bọn chị không dám ăn cay lắm, ăn xong có thể bị đau bụng, nhưng giờ cũng dần thích nghi rồi.\nLưu Minh: Đúng vậy, giờ bọn anh đều không sợ cay nữa. Gia Nguyệt, em là kiểu “không sợ cay” hay “sợ không cay”?\nBạch Gia Nguyệt: Tiếng Trung thật thú vị, cùng những chữ đó, chỉ đổi thứ tự là ý nghĩa đã thay đổi rồi.\nLý Văn: Trình độ tiếng Trung của em khá cao đấy, cái này cũng nghe hiểu được! Em nói đúng, “không sợ cay” là nói không sợ ăn món cay, “sợ không cay” là lo món chưa đủ cay đấy.\nBạch Gia Nguyệt: Em còn chưa đạt đến trình độ “sợ không cay”, thậm chí cũng không tính là “không sợ cay”, chỉ là thích ăn cay thôi.","audio_dialogue": "5-3.mp3","audio_vocab": "5-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "周末，白家月、陈天中、李文和安妮聚在一起吃午餐。白家月想吃辣的，要了辣子鸡；陈天中爱吃甸的，想尝尝松鼠鼟鱼；李文更喜欢吃咸的，选了红烧羊肉和一道凉菜；安妮听说贵州酸汤很有名，点了酸汤米线。他们边吃边聊，非常愉快。\n结账时，李文想请客，但大家觉得还是各付各的更合适。于是，李文付完钱后，大家把钱转给了他，还笑着说下次再一起聚餐。","pinyin": ""}],"translation_vn": "Cuối tuần, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và Annie tụ họp cùng nhau ăn trưa. Bạch Gia Nguyệt muốn ăn cay nên gọi món gà xào ớt; Trần Thiên Trung thích ăn ngọt, muốn nếm thử cá quế hình sóc; Lý Văn lại thích ăn mặn hơn, chọn thịt cừu kho đỏ và một món nguội; Annie nghe nói canh chua Quý Châu rất nổi tiếng nên gọi bún nước chua. Họ vừa ăn vừa trò chuyện, rất vui vẻ.\nKhi thanh toán, Lý Văn muốn mời cả nhóm, nhưng mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn. Thế là, sau khi Lý Văn trả tiền xong, mọi người chuyển tiền lại cho anh, còn cười nói lần sau lại cùng nhau tụ họp ăn uống.","audio_dialogue": "5-5.mp3","audio_vocab": "5-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "今天吃饭的时候，大家坐得比较随意。李文告诉白家月，在中国，正式聚餐和普通聚餐不同，正式聚餐时人们比较重视座位的安排，比如可以按照年龄大小来安排，年龄比较大的客人往往会坐在中间或者面对门口的座位。大家坐下时，主人会请客人先坐。如果聚餐时有老人，年轻人要等老人坐下后再坐。\n白家月听后觉得很有意思，她认为这么做是照顾客人、尊重老人的表现。","pinyin": ""}],"translation_vn": "Hôm nay lúc ăn cơm, mọi người ngồi khá tùy ý. Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, tụ họp ăn uống chính thức khác với tụ họp thông thường, khi tụ họp chính thức người ta khá coi trọng việc sắp xếp chỗ ngồi, chẳng hạn có thể sắp xếp theo tuổi tác, những vị khách lớn tuổi hơn thường sẽ ngồi ở giữa hoặc chỗ ngồi đối diện cửa ra vào. Khi mọi người ngồi xuống, chủ nhà sẽ mời khách ngồi trước. Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi.\nBạch Gia Nguyệt nghe xong cảm thấy rất thú vị, cô cho rằng làm như vậy là biểu hiện của việc quan tâm khách và tôn trọng người lớn tuổi.","audio_dialogue": "5-7.mp3","audio_vocab": "5-8.mp3"}]},{"id": 6,"title_cn": "我陪你去看病","title_pinyin": "","title_vn": "Tôi đưa bạn đi khám bệnh","goals": ["Có thể nghe hiểu và trao đổi các thông tin như tình trạng sức khỏe và phương án điều trị.","Có thể diễn đạt bằng lời nói hoặc chữ viết về quá trình đi khám bệnh.","Hiểu được quy trình cơ bản khi đi khám bệnh ở Trung Quốc."],"vocab": [{"hanzi": "咳嗽","pinyin": "késou","pos": "dgt.","vn": "ho"},{"hanzi": "咳","pinyin": "ké","pos": "dgt.","vn": "ho"},{"hanzi": "厉害","pinyin": "lìhai","pos": "tt.","vn": "nghiêm trọng, dữ dội"},{"hanzi": "严重","pinyin": "yánzhòng","pos": "tt.","vn": "nghiêm trọng"},{"hanzi": "赶快","pinyin": "gǎnkuài","pos": "phó.","vn": "nhanh chóng, ngay lập tức"},{"hanzi": "陪","pinyin": "péi","pos": "dgt.","vn": "đi cùng, tháp tùng"},{"hanzi": "翻译","pinyin": "fānyì","pos": "dgt./dt.","vn": "phiên dịch; người phiên dịch"},{"hanzi": "护士","pinyin": "hùshi","pos": "dt.","vn": "y tá"},{"hanzi": "表","pinyin": "biǎo","pos": "dt.","vn": "biểu mẫu, bảng"},{"hanzi": "性别","pinyin": "xìngbié","pos": "dt.","vn": "giới tính"},{"hanzi": "国籍","pinyin": "guójí","pos": "dt.","vn": "quốc tịch"},{"hanzi": "家庭","pinyin": "jiātíng","pos": "dt.","vn": "gia đình"},{"hanzi": "地址","pinyin": "dìzhǐ","pos": "dt.","vn": "địa chỉ"},{"hanzi": "挂号","pinyin": "guàhào","pos": "dgt.","vn": "đăng ký khám bệnh"},{"hanzi": "排队","pinyin": "páiduì","pos": "dgt.","vn": "xếp hàng"},{"hanzi": "大厅","pinyin": "dàtīng","pos": "dt.","vn": "sảnh lớn, đại sảnh"},{"hanzi": "偶尔","pinyin": "ǔ'ěr","pos": "phó./tt.","vn": "thỉnh thoảng; không thường xuyên"},{"hanzi": "身","pinyin": "shēn","pos": "dt./lượng.","vn": "thân, người; (lượng từ chỉ) bộ (quần áo)"},{"hanzi": "结果","pinyin": "jiéguǒ","pos": "dt./liên.","vn": "kết quả; kết quả là"},{"hanzi": "性","pinyin": "xìng","pos": "htố.","vn": "(hậu tố chỉ tính chất, đặc điểm, phạm vi nhất định)"},{"hanzi": "体温","pinyin": "tǐwēn","pos": "dt.","vn": "thân nhiệt"},{"hanzi": "降","pinyin": "jiàng","pos": "dgt.","vn": "hạ, giảm"},{"hanzi": "光","pinyin": "guāng","pos": "phó.","vn": "chỉ, chỉ riêng"},{"hanzi": "打针","pinyin": "dǎhēn","pos": "dgt.","vn": "tiêm (thuốc)"},{"hanzi": "有效","pinyin": "yǒuxiào","pos": "dgt.","vn": "có hiệu quả"},{"hanzi": "按时","pinyin": "ànshí","pos": "phó.","vn": "đúng giờ, đúng thời gian quy định"},{"hanzi": "汗","pinyin": "hàn","pos": "dt.","vn": "mồ hôi"},{"hanzi": "醒","pinyin": "xǐng","pos": "dgt.","vn": "tỉnh dậy, thức giấc"},{"hanzi": "感觉","pinyin": "gǎnjué","pos": "dgt./dt.","vn": "cảm thấy; cảm giác"},{"hanzi": "低","pinyin": "dī","pos": "tt.","vn": "thấp"},{"hanzi": "难受","pinyin": "nánshòu","pos": "tt.","vn": "khó chịu"},{"hanzi": "通","pinyin": "tōng","pos": "dgt.","vn": "hiểu, thông suốt"},{"hanzi": "过程","pinyin": "guòchéng","pos": "dt.","vn": "quá trình"},{"hanzi": "部","pinyin": "bù","pos": "dt.","vn": "khoa, bộ phận"},{"hanzi": "收费","pinyin": "shōufei","pos": "dgt.","vn": "thu phí"},{"hanzi": "情况","pinyin": "qíngkuàng","pos": "dt.","vn": "tình hình"},{"hanzi": "好","pinyin": "hǎo","pos": "dgt.","vn": "để, nhằm"},{"hanzi": "治疗","pinyin": "zhìliáo","pos": "dgt.","vn": "điều trị"},{"hanzi": "步","pinyin": "bù","pos": "dt.","vn": "bước"}],"grammar": [{"title": "形容词“厉害” Tính từ “厉害”","explanation_vn": "Tính từ \"厉害\" có thể đặt sau động từ hoặc tính từ, biểu thị mức độ rất cao, cấu trúc là \"động từ + được + (phó từ) + 厉害\" hoặc \"tính từ + được + 厉害\".","examples": [{"cn": "我还发烧，一直咳嗽，咳得很厉害。","pinyin": "","vn": "Tôi còn bị sốt, cứ ho mãi, ho rất dữ dội."},{"cn": "我昨天跑步跑多了，今天腐疼得厉害。","pinyin": "","vn": "Hôm qua tôi chạy bộ nhiều quá, hôm nay chân đau kinh khủng."},{"cn": "这道菜辣得厉害，我吃了一口就不敢再吃了。","pinyin": "","vn": "Món này cay kinh khủng, tôi ăn một miếng là không dám ăn nữa."}]},{"title": "固定格式“（没）有什么（好）×的” Cấu trúc cố định “（没）有什么（好）×的”","explanation_vn": "Cấu trúc cố định \"(没)有什么(好)×的\" biểu thị không cần thiết phải làm việc gì đó, hoặc có một cảm giác, trạng thái nào đó.","examples": [{"cn": "你跟我有什么好客气的。","pinyin": "","vn": "Bạn với tôi thì có gì phải khách sáo chứ."},{"cn": "这种事在网上有很多，没有什么奇怪的。","pinyin": "","vn": "Chuyện như vậy trên mạng có nhiều lắm, chẳng có gì lạ cả."},{"cn": "我觉得这家商场里的东西都很一般，没有什么好买的。","pinyin": "","vn": "Tôi thấy đồ trong trung tâm thương mại này đều bình thường, chẳng có gì đáng mua cả."}]},{"title": "频率副词“偶尔” Phó từ tần suất “偶尔”","explanation_vn": "Phó từ tần suất \"偶尔\" biểu thị hành động hoặc tình huống xảy ra rất ít lần.","examples": [{"cn": "她告诉医生，自己平时身体不错，偶尔才会生一次病。","pinyin": "","vn": "Cô ấy nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần."},{"cn": "他经常在家看电影，偶尔才去电影院看。","pinyin": "","vn": "Anh ấy thường xem phim ở nhà, thỉnh thoảng mới đến rạp chiếu phim xem."},{"cn": "我一般都在学校食堂吃饭，偶尔会跟朋友一起出去吃。","pinyin": "","vn": "Tôi thường ăn ở căng tin trường, thỉnh thoảng mới cùng bạn bè ra ngoài ăn."}]},{"title": "目的复句“……，好……” Câu phức chỉ mục đích “……，好……”","explanation_vn": "Vế trước nói về một hành động hay tình huống nào đó, vế sau nêu rõ mục đích của hành động hay tình huống đó.","examples": [{"cn": "医生有时还会做一些检查，好给出合适的治疗方法。","pinyin": "","vn": "Bác sĩ đôi khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp."},{"cn": "你们先了解一下情况，好做出决定。","pinyin": "","vn": "Các bạn hãy tìm hiểu tình hình trước, để đưa ra quyết định."},{"cn": "我把电话号码告诉你，以后有什么事好联系我。","pinyin": "","vn": "Tôi cho bạn số điện thoại, sau này có việc gì thì tiện liên lạc với tôi."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "白家月","cn": "喜，李文，我身体不舒服。","pinyin": ""},{"speaker": "李文","cn": "你怎么了？听你的声音，好像感冒了。","pinyin": ""},{"speaker": "白家月","cn": "对，我还发烧，一直咳嗽，咳得很厉害。","pinyin": ""},{"speaker": "李文","cn": "那挺严重的，最好赶快去医院检查一下。","pinyin": ""},{"speaker": "白家月","cn": "我也这么想，不过我来中国后还没去过医院，不知道怎么在中国的医院看病。","pinyin": ""},{"speaker": "李文","cn": "没关系，我陪你一起去，还能帮你翻译。你在家等一下，我现在就去接你。","pinyin": ""},{"speaker": "白家月","cn": "太好了！有你陪着，我就放心多了。","pinyin": ""}],"translation_vn": "Bạch Gia Nguyệt: Alo, Lý Văn, mình thấy khó chịu trong người.\nLý Văn: Bạn làm sao vậy? Nghe giọng có vẻ bị cảm rồi.\nBạch Gia Nguyệt: Đúng vậy, mình còn bị sốt, cứ ho mãi, ho rất dữ dội.\nLý Văn: Nghe có vẻ nghiêm trọng đấy, tốt nhất nên nhanh chóng đến bệnh viện kiểm tra một lần.\nBạch Gia Nguyệt: Mình cũng nghĩ vậy, nhưng từ khi đến Trung Quốc mình chưa đi bệnh viện lần nào, không biết cách khám bệnh ở bệnh viện Trung Quốc như thế nào.\nLý Văn: Không sao, mình đi cùng bạn, còn có thể giúp bạn phiên dịch nữa. Bạn ở nhà đợi một lát, mình đến đón bạn ngay bây giờ.\nBạch Gia Nguyệt: Tuyệt quá! Có bạn đi cùng, mình yên tâm hơn nhiều rồi.","audio_dialogue": "6-1.mp3","audio_vocab": "6-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "李文","cn": "护士，您好，我的这位外国朋友生病了，第一次来这里看病，需要怎么做？","pinyin": ""},{"speaker": "护士","cn": "请在这张表上写上病人的姓名、性别、国籍、年龄、电话号码和家庭地址。","pinyin": ""},{"speaker": "李文","cn": "我写好了，您看看，这样可以吗？","pinyin": ""},{"speaker": "护士","cn": "没问题，您拿着病人的护照去挂号吧。","pinyin": ""},{"speaker": "李文","cn": "家月，我去排队挂号，你先在大厅休息，别着急。","pinyin": ""},{"speaker": "白家月","cn": "好的，真是太谢谢你了！","pinyin": ""},{"speaker": "李文","cn": "你跟我有什么好客气的。","pinyin": ""}],"translation_vn": "Lý Văn: Chào y tá, bạn nước ngoài của tôi bị ốm, đây là lần đầu tiên bạn ấy đến đây khám bệnh, cần làm thế nào ạ?\nY tá: Xin anh điền vào biểu mẫu này họ tên, giới tính, quốc tịch, tuổi, số điện thoại và địa chỉ gia đình của bệnh nhân.\nLý Văn: Tôi viết xong rồi, chị xem giúp, thế này được chưa ạ?\nY tá: Không có vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám bệnh nhé.\nLý Văn: Gia Nguyệt, mình đi xếp hàng đăng ký khám đây, bạn cứ nghỉ ở sảnh trước, đừng lo lắng.\nBạch Gia Nguyệt: Được rồi, thật sự cảm ơn bạn nhiều lắm!\nLý Văn: Bạn với mình thì có gì phải khách sáo chứ.","audio_dialogue": "6-3.mp3","audio_vocab": "6-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "下午白家月去看病了，她告诉医生，自己平时身体不错，偶尔才会生一次病。这次她病得很厉害，头也一直疼，身上一点儿力气都没有。医生给她做了检查，检查结果出来后，发现她得了比较严重的流行性感冒。\n医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效。医生还让她回家以后按时吃药，多喝水，多休息。\n晚上，白家月睡觉时出了一身汗。第二天醒来时，她感觉头不那么疼了，体温也低了一些，身体不那么难受了。","pinyin": ""}],"translation_vn": "Buổi chiều Bạch Gia Nguyệt đi khám bệnh, cô nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần. Lần này cô bị bệnh khá nặng, đầu cứ đau mãi, người không còn chút sức lực nào. Bác sĩ đã khám cho cô, sau khi có kết quả kiểm tra, phát hiện cô bị cúm mùa khá nghiêm trọng.\nBác sĩ nói với cô rằng bây giờ cần hạ thân nhiệt xuống, chỉ uống thuốc thôi e là chưa đủ, tiêm thuốc sẽ hiệu quả hơn. Bác sĩ còn dặn cô về nhà uống thuốc đúng giờ, uống nhiều nước, nghỉ ngơi nhiều.\nBuổi tối, lúc ngủ Bạch Gia Nguyệt đổ một thân mồ hôi. Sáng hôm sau tỉnh dậy, cô cảm thấy đầu đỡ đau hơn, thân nhiệt cũng hạ xuống một chút, người không còn khó chịu như trước nữa.","audio_dialogue": "6-5.mp3","audio_vocab": "6-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "外国人第一次在中国看病，可能会担心语言不通，或者觉得看病的过程和自己的国家不同。其实，这些问题都有办法解决。\n有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高。如果没有特别需要，可以选择普通部，用简单的中文和医生交流。\n在中国看病要先挂号，然后再去找医生。医生会问病人的情况，有时还会做一些检查，好给出合适的治疗方法。只要按照医生说的一步一步来，一般都可以顺利得到治疗。","pinyin": ""}],"translation_vn": "Người nước ngoài lần đầu đi khám bệnh ở Trung Quốc có thể lo lắng về bất đồng ngôn ngữ, hoặc cảm thấy quy trình khám bệnh khác với đất nước mình. Thực ra, những vấn đề này đều có cách giải quyết.\nMột số bệnh viện có khoa quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí của khoa quốc tế lại khá cao. Nếu không có nhu cầu đặc biệt, có thể chọn khoa thường, dùng tiếng Trung đơn giản để giao tiếp với bác sĩ.\nKhám bệnh ở Trung Quốc cần đăng ký trước, sau đó mới đi gặp bác sĩ. Bác sĩ sẽ hỏi tình hình của bệnh nhân, có khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp. Chỉ cần làm theo từng bước mà bác sĩ nói, nhìn chung đều có thể được điều trị thuận lợi.","audio_dialogue": "6-7.mp3","audio_vocab": "6-8.mp3"}]},{"id": 7,"title_cn": "在工作中学习","title_pinyin": "","title_vn": "Học hỏi trong công việc","goals": ["Có thể nghe hiểu và trao đổi về nhiệm vụ công việc, sắp xếp công việc và các nội dung liên quan.","Có thể trình bày bằng lời nói hoặc văn bản kinh nghiệm làm việc và đưa ra lời khuyên về phát triển sự nghiệp.","Hiểu được cách làm việc coi trọng học hỏi và tích lũy kinh nghiệm trong môi trường công sở."],"vocab": [{"hanzi": "打扰","pinyin": "dǎrǎo","pos": "dgt.","vn": "làm phiền, quấy rầy"},{"hanzi": "市场","pinyin": "shìchǎng","pos": "dt.","vn": "thị trường, chợ"},{"hanzi": "调查","pinyin": "diàochá","pos": "dgt.","vn": "điều tra, khảo sát"},{"hanzi": "计划","pinyin": "jìhuà","pos": "dt./dgt.","vn": "kế hoạch; lập kế hoạch"},{"hanzi": "内容","pinyin": "nèiróng","pos": "dt.","vn": "nội dung"},{"hanzi": "改","pinyin": "gǎi","pos": "dgt.","vn": "sửa, thay đổi"},{"hanzi": "细心","pinyin": "xìxīn","pos": "tt.","vn": "cẩn thận, tỉ mỉ"},{"hanzi": "客户","pinyin": "kèhù","pos": "dt.","vn": "khách hàng"},{"hanzi": "真正","pinyin": "zhēnzhèng","pos": "tt./phó.","vn": "thực sự, chân chính"},{"hanzi": "想法","pinyin": "xiǎngfǎ","pos": "dt.","vn": "ý kiến, suy nghĩ"},{"hanzi": "任务","pinyin": "rènwù","pos": "dt.","vn": "nhiệm vụ"},{"hanzi": "及时","pinyin": "jíshí","pos": "phó./tt.","vn": "kịp thời"},{"hanzi": "出差","pinyin": "chūchāi","pos": "dgt.","vn": "đi công tác"},{"hanzi": "经验","pinyin": "jīngyàn","pos": "dt.","vn": "kinh nghiệm"},{"hanzi": "采访","pinyin": "cǎifǎng","pos": "dgt.","vn": "phỏng vấn"},{"hanzi": "产品","pinyin": "chǎnpǐn","pos": "dt.","vn": "sản phẩm"},{"hanzi": "看法","pinyin": "kànfǎ","pos": "dt.","vn": "quan điểm, cách nhìn"},{"hanzi": "提前","pinyin": "tíqián","pos": "dgt.","vn": "làm trước, tiến hành sớm"},{"hanzi": "便于","pinyin": "biànyú","pos": "dgt.","vn": "thuận tiện cho"},{"hanzi": "既然","pinyin": "jìrán","pos": "liên.","vn": "đã như vậy thì, bởi vì"},{"hanzi": "谈","pinyin": "tán","pos": "dgt.","vn": "bàn bạc, nói chuyện"},{"hanzi": "笔","pinyin": "bǐ","pos": "lượng.","vn": "khoản (dùng cho tiền bạc, tài khoản...)"},{"hanzi": "生意","pinyin": "shēngyi","pos": "dt.","vn": "công việc kinh doanh, buôn bán"},{"hanzi": "困难","pinyin": "kùnnan","pos": "dt./tt.","vn": "khó khăn"},{"hanzi": "优点","pinyin": "yōudiǎn","pos": "dt.","vn": "ưu điểm"},{"hanzi": "缺点","pinyin": "quēdiǎn","pos": "dt.","vn": "khuyết điểm, nhược điểm"},{"hanzi": "实际","pinyin": "shíjì","pos": "tt./dt.","vn": "thực tế"},{"hanzi": "效果","pinyin": "xiàoguǒ","pos": "dt.","vn": "hiệu quả"},{"hanzi": "点","pinyin": "diǎn","pos": "dt.","vn": "điểm"},{"hanzi": "一下","pinyin": "yíxià","pos": "phó.","vn": "ngay lập tức, bỗng nhiên"},{"hanzi": "份","pinyin": "fèn","pos": "lượng.","vn": "phần, bản (dùng để chỉ phần, bản, bộ...)"},{"hanzi": "积累","pinyin": "jīlěi","pos": "dgt.","vn": "tích lũy"},{"hanzi": "使","pinyin": "shǐ","pos": "dgt.","vn": "khiến cho, làm cho"},{"hanzi": "进入","pinyin": "jìnrù","pos": "dgt.","vn": "tiến vào, bước vào"},{"hanzi": "社会","pinyin": "shèhuì","pos": "dt.","vn": "xã hội"},{"hanzi": "管理","pinyin": "guǎnlǐ","pos": "dgt.","vn": "quản lý"},{"hanzi": "基础","pinyin": "jīchǔ","pos": "dt.","vn": "nền tảng, cơ sở"},{"hanzi": "能力","pinyin": "nénglì","pos": "dt.","vn": "năng lực"},{"hanzi": "今后","pinyin": "jīnhòu","pos": "dt.","vn": "từ nay về sau, tương lai"}],"grammar": [{"title": "固定格式\"在……方面\"","explanation_vn": "Cấu trúc cố định \"在……方面\" (về mặt...) dùng để giới hạn phạm vi hoặc lĩnh vực đang bàn luận.","examples": [{"cn": "在内容方面，您觉得有需要改的吗？","pinyin": "","vn": "Về mặt nội dung, chị thấy có cần sửa gì không?"},{"cn": "在时间安排方面，你可以再想一想。","pinyin": "","vn": "Về mặt sắp xếp thời gian, bạn có thể suy nghĩ thêm."},{"cn": "他才来中国两个月，在生活方面，还不太习惯。","pinyin": "","vn": "Anh ấy mới đến Trung Quốc được hai tháng, về mặt sinh hoạt, vẫn chưa quen lắm."}]},{"title": "因果复句\"既然……，就……\"","explanation_vn": "Câu phức nhân quả \"既然……，就……\" (đã như vậy thì...): vế trước nêu tiền đề, vế sau nêu kết luận được suy ra từ tiền đề đó.","examples": [{"cn": "既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin": "","vn": "Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích."},{"cn": "既然大家都同意，我们就这么做吧。","pinyin": "","vn": "Đã mọi người đều đồng ý thì chúng ta cứ làm như vậy đi."},{"cn": "既然你们已经决定了，就不要再改了。","pinyin": "","vn": "Đã các bạn quyết định rồi thì đừng thay đổi nữa."}]},{"title": "固定格式\"拿……来说\"","explanation_vn": "Cấu trúc cố định \"拿……来说\" (lấy... mà nói) dùng để dẫn ra một khía cạnh cụ thể hoặc ví dụ.","examples": [{"cn": "拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","pinyin": "","vn": "Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý."},{"cn": "现在的生活很方便。拿购物来说，人们不出门就能买到想要的东西。","pinyin": "","vn": "Cuộc sống hiện nay rất tiện lợi. Lấy việc mua sắm mà nói, người ta không cần ra khỏi nhà cũng có thể mua được thứ mình muốn."},{"cn": "在中国，南北方的生活习惯不同。拿吃饭来说，一般南方人更爱吃米饭。","pinyin": "","vn": "Ở Trung Quốc, thói quen sinh hoạt giữa miền Nam và miền Bắc khác nhau. Lấy việc ăn uống mà nói, người miền Nam nhìn chung thích ăn cơm hơn."}]},{"title": "兼语句\"主语+使+宾语+动词短语\"","explanation_vn": "Câu kiêm ngữ \"chủ ngữ + 使 + tân ngữ + cụm động từ\" biểu thị một tình huống hoặc nguyên nhân nào đó khiến người hoặc sự vật xảy ra thay đổi hoặc tạo ra kết quả.","examples": [{"cn": "如果总是换工作，可能会使自己的发展受到影响。","pinyin": "","vn": "Nếu cứ liên tục đổi việc, có thể sẽ khiến sự phát triển của bản thân bị ảnh hưởng."},{"cn": "这个新方法使工作变得更加简单了。","pinyin": "","vn": "Phương pháp mới này khiến công việc trở nên đơn giản hơn."},{"cn": "参加这些交流活动使留学生更快适应了大学生活。","pinyin": "","vn": "Việc tham gia các hoạt động giao lưu này giúp lưu học sinh thích nghi nhanh hơn với cuộc sống đại học."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "同事","cn": "经理，打扰您一下。市场调查的计划书我昨天发到您邮箱了。在内容方面，您觉得有需要改的吗？","pinyin": ""},{"speaker": "王一雪","cn": "我看过了，写得不错，就是调查的地点只有超市，不太够。","pinyin": ""},{"speaker": "同事","cn": "好的，那我再加一些网店。","pinyin": ""},{"speaker": "王一雪","cn": "行。做调查的时候要细心，注意了解客户真正的想法。","pinyin": ""},{"speaker": "同事","cn": "明白了，我会认真准备，按时完成任务。","pinyin": ""},{"speaker": "王一雪","cn": "嗯，如果遇到什么问题，及时跟我联系。","pinyin": ""}],"translation_vn": "Đồng nghiệp: Giám đốc, làm phiền chị một chút. Bản kế hoạch khảo sát thị trường em đã gửi vào email của chị hôm qua rồi. Về mặt nội dung, chị thấy có cần sửa gì không ạ?\nVương Nhất Tuyết: Chị xem rồi, viết khá tốt, chỉ có điều địa điểm khảo sát chỉ có siêu thị, chưa đủ.\nĐồng nghiệp: Vâng, vậy em sẽ thêm một số cửa hàng trực tuyến.\nVương Nhất Tuyết: Được. Khi khảo sát phải cẩn thận, chú ý tìm hiểu suy nghĩ thực sự của khách hàng.\nĐồng nghiệp: Em hiểu rồi, em sẽ chuẩn bị kỹ càng, hoàn thành nhiệm vụ đúng hạn.\nVương Nhất Tuyết: Ừ, nếu gặp vấn đề gì thì liên hệ với chị kịp thời nhé.","audio_dialogue": "7-1.mp3","audio_vocab": "7-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "同事","cn": "杨哥，经理让我下周去上海出差，做市场调查，你有这方面的经验吗？","pinyin": ""},{"speaker": "杨同乐","cn": "你要去几天？主要调查什么内容？","pinyin": ""},{"speaker": "同事","cn": "去四天，打算采访一些客户，了解他们对新产品的看法。","pinyin": ""},{"speaker": "杨同乐","cn": "那你要提前准备好问题，便于和客户交流。","pinyin": ""},{"speaker": "同事","cn": "好的，我已经准备了一些问题。","pinyin": ""},{"speaker": "杨同乐","cn": "很好。既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin": ""}],"translation_vn": "Đồng nghiệp: Anh Dương, giám đốc bảo em tuần sau đi công tác Thượng Hải, làm khảo sát thị trường, anh có kinh nghiệm về việc này không?\nDương Đồng Lạc: Em đi mấy ngày? Chủ yếu khảo sát nội dung gì?\nĐồng nghiệp: Đi bốn ngày, em định phỏng vấn một số khách hàng, tìm hiểu ý kiến của họ về sản phẩm mới.\nDương Đồng Lạc: Vậy em phải chuẩn bị trước các câu hỏi, để thuận tiện giao tiếp với khách hàng.\nĐồng nghiệp: Vâng, em đã chuẩn bị sẵn một số câu hỏi rồi.\nDương Đồng Lạc: Tốt lắm. Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích.","audio_dialogue": "7-3.mp3","audio_vocab": "7-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "前段时间，杨同乐的同事谈成了一笔不错的生意。刚开始，这位同事也遇到了一些困难。拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。杨同乐告诉她，这是因为她介绍的方式都一样。其实，不同年龄、不同性别的客户对产品的关注点是不一样的。于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多。","pinyin": ""}],"translation_vn": "Một thời gian trước, đồng nghiệp của Dương Đồng Lạc đã đàm phán thành công một thương vụ khá tốt. Lúc đầu, đồng nghiệp này cũng gặp phải một số khó khăn. Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý. Dương Đồng Lạc nói với cô ấy rằng đó là vì cách giới thiệu của cô lúc nào cũng giống nhau. Thực ra, khách hàng ở độ tuổi khác nhau, giới tính khác nhau sẽ có những điểm quan tâm khác nhau đối với sản phẩm. Thế là, đồng nghiệp này lại nghiêm túc tiến hành khảo sát thị trường thêm vài lần nữa, tìm hiểu suy nghĩ của các khách hàng khác nhau. Sau đó khi đối diện với các khách hàng khác nhau, cô ấy có thể giới thiệu sản phẩm theo tình hình của từng người, hiệu quả nhờ đó tốt lên rất nhiều.","audio_dialogue": "7-5.mp3","audio_vocab": "7-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "有的年轻人经常换工作，总觉得下一份工作会更好。但是，适应新工作往往需要比较长的时间。如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响。我认为，年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。只有把这些基础打好，提高工作能力，今后才会有更好的发展机会。","pinyin": ""}],"translation_vn": "Có những người trẻ thường xuyên đổi việc, luôn cảm thấy công việc tiếp theo sẽ tốt hơn. Nhưng thích nghi với công việc mới thường cần một khoảng thời gian khá dài. Nếu cứ liên tục đổi việc, không những khó tích lũy kinh nghiệm, mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng. Tôi cho rằng, khi người trẻ mới bước vào xã hội, không nên chỉ quan tâm đến mức lương cao hay thấp, mà càng phải coi trọng việc học hỏi. Ví dụ như học những kiến thức chuyên môn không có trong sách giáo khoa, tìm hiểu cách quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp, v.v. Chỉ khi xây dựng tốt những nền tảng này, nâng cao năng lực làm việc, thì sau này mới có cơ hội phát triển tốt hơn.","audio_dialogue": "7-7.mp3","audio_vocab": "7-8.mp3"}]},{"id": 8,"title_cn": "该放松时就放松","title_pinyin": "","title_vn": "Khi cần thư giãn thì hãy thư giãn","goals": ["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến phương pháp và cách thức giảm căng thẳng.","Có thể trình bày bằng lời nói hoặc văn bản quan điểm về việc giảm căng thẳng và thư giãn.","Hiểu được vào cuối tuần người Trung Quốc thường đi đâu để thư giãn."],"vocab": [{"hanzi": "紧张","pinyin": "jǐnzhāng","pos": "tt.","vn": "căng thẳng; (nguồn cung) khan hiếm"},{"hanzi": "放松","pinyin": "fàngsōng","pos": "dgt.","vn": "thư giãn, thả lỏng"},{"hanzi": "呀","pinyin": "yā","pos": "ct.","vn": "ôi, ồ (thán từ)"},{"hanzi": "不管","pinyin": "bùguǎn","pos": "liên.","vn": "bất kể, dù cho"},{"hanzi": "郊区","pinyin": "jiāoqū","pos": "dt.","vn": "ngoại ô"},{"hanzi": "游玩","pinyin": "yóuwán","pos": "dgt.","vn": "đi chơi, du ngoạn"},{"hanzi": "主意","pinyin": "zhǔyi","pos": "dt.","vn": "ý kiến, chủ ý"},{"hanzi": "外出","pinyin": "wàichū","pos": "dgt.","vn": "ra ngoài, đi ra ngoài"},{"hanzi": "戴","pinyin": "dài","pos": "dgt.","vn": "đội, đeo"},{"hanzi": "帽子","pinyin": "màozi","pos": "dt.","vn": "mũ, nón"},{"hanzi": "长城","pinyin": "Chángchéng","pos": "danh từ riêng","vn": "Vạn Lý Trường Thành"},{"hanzi": "项目","pinyin": "xiàngmù","pos": "dt.","vn": "dự án"},{"hanzi": "加班","pinyin": "jiābān","pos": "dgt.","vn": "làm thêm giờ, tăng ca"},{"hanzi": "熬夜","pinyin": "áoyè","pos": "dgt.","vn": "thức khuya"},{"hanzi": "否则","pinyin": "fǒuzé","pos": "liên.","vn": "nếu không thì"},{"hanzi": "失去","pinyin": "shīqù","pos": "dgt.","vn": "mất đi, đánh mất"},{"hanzi": "值得","pinyin": "zhídé","pos": "dgt.","vn": "đáng, xứng đáng"},{"hanzi": "暂停","pinyin": "zàntíng","pos": "dgt.","vn": "tạm dừng"},{"hanzi": "之后","pinyin": "zhīhòu","pos": "dt.","vn": "sau đó, sau khi"},{"hanzi": "风景","pinyin": "fēngjǐng","pos": "dt.","vn": "phong cảnh"},{"hanzi": "效率","pinyin": "xiàolǜ","pos": "dt.","vn": "hiệu suất"},{"hanzi": "下降","pinyin": "xiàjiàng","pos": "dgt.","vn": "giảm xuống, hạ xuống"},{"hanzi": "相比","pinyin": "xiāngbǐ","pos": "dgt.","vn": "so với, so sánh"},{"hanzi": "因此","pinyin": "yīncǐ","pos": "liên.","vn": "do đó, vì vậy"},{"hanzi": "提醒","pinyin": "tíxǐng","pos": "dgt.","vn": "nhắc nhở"},{"hanzi": "与","pinyin": "yǔ","pos": "giới./liên.","vn": "với; và"},{"hanzi": "大自然","pinyin": "dàzìrán","pos": "dt.","vn": "thiên nhiên"},{"hanzi": "美丽","pinyin": "měilì","pos": "tt.","vn": "đẹp, xinh đẹp"},{"hanzi": "景色","pinyin": "jǐngsè","pos": "dt.","vn": "cảnh sắc, phong cảnh"},{"hanzi": "首都","pinyin": "shǒudū","pos": "dt.","vn": "thủ đô"},{"hanzi": "市区","pinyin": "shìqū","pos": "dt.","vn": "khu vực nội thành"},{"hanzi": "眼前","pinyin": "yǎnqián","pos": "dt.","vn": "trước mắt"},{"hanzi": "美景","pinyin": "měijǐng","pos": "dt.","vn": "cảnh đẹp"},{"hanzi": "参观","pinyin": "cānguān","pos": "dgt.","vn": "tham quan"},{"hanzi": "景点","pinyin": "jǐngdiǎn","pos": "dt.","vn": "điểm tham quan, danh lam thắng cảnh"},{"hanzi": "交通","pinyin": "jiāotōng","pos": "dt.","vn": "giao thông"},{"hanzi": "乘坐","pinyin": "chéngzuò","pos": "dgt.","vn": "đi, ngồi (xe, tàu...)"},{"hanzi": "十分","pinyin": "shífēn","pos": "phó.","vn": "rất, vô cùng"},{"hanzi": "实际上","pinyin": "shíjìshàng","pos": "phó.","vn": "thực tế thì, trên thực tế"},{"hanzi": "故宫","pinyin": "Gùgōng","pos": "danh từ riêng","vn": "Cố Cung (Tử Cấm Thành)"}],"grammar": [{"title": "条件复句\"不管……，都/也……\"","explanation_vn": "Câu phức điều kiện \"不管……，都/也……\" (bất kể... đều/cũng...): vế trước nêu một điều kiện có khả năng xảy ra, vế sau biểu thị kết quả không thay đổi. Cấu trúc cơ bản: 不管 + điều kiện/tình huống/sự thay đổi, (chủ ngữ) + 都/也 + kết quả.","examples": [{"cn": "不管去哪儿，能放松的地方都行。","pinyin": "","vn": "Bất kể đi đâu, chỉ cần là nơi có thể thư giãn thì đều được."},{"cn": "不管有什么想法，你都要说出来，让我们知道。","pinyin": "","vn": "Bất kể có suy nghĩ gì, bạn đều phải nói ra để chúng tôi biết."},{"cn": "不管遇到多大困难，我们也要坚持，最后一定能完成任务。","pinyin": "","vn": "Bất kể gặp phải khó khăn lớn đến đâu, chúng ta cũng phải kiên trì, cuối cùng nhất định sẽ hoàn thành được nhiệm vụ."}]},{"title": "假设复句\"……，否则……\"","explanation_vn": "Câu phức giả thiết \"……，否则……\" (…, nếu không thì…): vế trước nêu ra yêu cầu, đề nghị hoặc điều kiện, vế sau nói rõ hậu quả sẽ xảy ra nếu tình huống ở vế trước không được thực hiện.","examples": [{"cn": "还是别给自己太大压力，否则，失去健康就不值得了。","pinyin": "","vn": "Tốt nhất đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng chút nào."},{"cn": "今晚早点儿睡吧，否则明天早上起不来，又该迟到了。","pinyin": "","vn": "Tối nay ngủ sớm một chút đi, nếu không sáng mai dậy không nổi, lại trễ giờ mất."},{"cn": "吃不完的菜要放进冰箱，否则很容易坏。","pinyin": "","vn": "Thức ăn không ăn hết phải cho vào tủ lạnh, nếu không rất dễ bị hỏng."}]},{"title": "比较句\"跟……相比\"","explanation_vn": "\"跟……相比\" (so với...) là cấu trúc biểu thị sự so sánh. Giới từ \"跟\" thường được dùng trong khẩu ngữ, trong những hoàn cảnh không trang trọng lắm. Trong văn viết, trong những hoàn cảnh trang trọng thường dùng \"与\".","examples": [{"cn": "跟一直加班相比，休息好了再工作，效率更高。","pinyin": "","vn": "So với việc cứ liên tục làm thêm giờ, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn."},{"cn": "跟读研究生相比，我更想直接工作。","pinyin": "","vn": "So với việc học lên thạc sĩ, tôi muốn đi làm trực tiếp hơn."},{"cn": "跟用现金相比，手机支付更方便些。","pinyin": "","vn": "So với việc dùng tiền mặt, thanh toán bằng điện thoại tiện lợi hơn một chút."}]},{"title": "固定短语\"有A有B\"","explanation_vn": "Trong cụm từ cố định \"有A有B\" (có A có B), A và B phần lớn là dạng đơn âm tiết, một số ít là dạng song âm tiết. A và B thường có ý nghĩa liên quan, gần giống hoặc đối lập nhau.","examples": [{"cn": "郊区有山有水，还有很多农家乐。","pinyin": "","vn": "Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại."},{"cn": "超市里的苹果有大有小，有红有绿，看起来都非常好吃。","pinyin": "","vn": "Táo trong siêu thị có to có nhỏ, có đỏ có xanh, trông đều rất ngon."},{"cn": "春天，公园里到处都是人，有男有女，有大人有孩子，特别热闹。","pinyin": "","vn": "Mùa xuân, trong công viên đâu đâu cũng là người, có nam có nữ, có người lớn có trẻ em, rất náo nhiệt."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "安妮","cn": "家月，最近学习太紧张了，咱们明天出去放松放松吧。","pinyin": ""},{"speaker": "白家月","cn": "呀，正好我也想出去呢。咱们去哪儿好呢？","pinyin": ""},{"speaker": "安妮","cn": "不管去哪儿，能放松的地方都行。","pinyin": ""},{"speaker": "白家月","cn": "郊区怎么样？","pinyin": ""},{"speaker": "安妮","cn": "天中说，下周王老师要带咱们去郊区游玩呢。","pinyin": ""},{"speaker": "白家月","cn": "是吗？那咱们明天去爬长城吧，不是说\"不到长城非好汉\"吗？","pinyin": ""},{"speaker": "安妮","cn": "好主意！不过明天是个大晴天，外出记得戴帽子。","pinyin": ""}],"translation_vn": "Annie: Gia Nguyệt, dạo này học hành căng thẳng quá, ngày mai chúng mình ra ngoài thư giãn một chút đi.\nBạch Gia Nguyệt: Ôi, đúng lúc mình cũng muốn ra ngoài đây. Chúng mình đi đâu nhỉ?\nAnnie: Bất kể đi đâu, chỗ nào có thể thư giãn là được.\nBạch Gia Nguyệt: Đi ngoại ô thì sao?\nAnnie: Thiên Trung nói tuần sau thầy Vương sẽ dẫn chúng mình đi chơi ngoại ô đấy.\nBạch Gia Nguyệt: Thật à? Vậy ngày mai chúng mình đi leo Vạn Lý Trường Thành đi, chẳng phải người ta nói \"chưa đến Trường Thành chưa phải hảo hán\" sao?\nAnnie: Ý hay đấy! Nhưng ngày mai trời nắng to, ra ngoài nhớ đội mũ nhé.","audio_dialogue": "8-1.mp3","audio_vocab": "8-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "李文","cn": "同乐哥，你们平时工作忙吗？","pinyin": ""},{"speaker": "杨同乐","cn": "挺忙的。以前我总觉得年轻时要多学多干，所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯。","pinyin": ""},{"speaker": "李文","cn": "还是别给自己太大压力，否则，失去健康就不值得了。","pinyin": ""},{"speaker": "杨同乐","cn": "是啊，后来我就不接那么多项目了。我发现暂停下来、好好休息之后，我能把工作做得更快更好。","pinyin": ""},{"speaker": "李文","cn": "对，该工作时就工作，该放松时就要放松。","pinyin": ""},{"speaker": "杨同乐","cn": "是的，现在我周末常来郊区，在好山好水好风景中放松自己。","pinyin": ""}],"translation_vn": "Lý Văn: Anh Đồng Lạc, mọi người thường ngày làm việc bận không?\nDương Đồng Lạc: Khá bận. Trước đây anh luôn nghĩ rằng lúc còn trẻ phải học nhiều làm nhiều, nên đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, sức khỏe cũng báo động rồi.\nLý Văn: Vẫn nên đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng đâu.\nDương Đồng Lạc: Đúng vậy, sau đó anh không nhận nhiều dự án như thế nữa. Anh phát hiện ra rằng sau khi tạm dừng lại, nghỉ ngơi thật tốt, anh có thể làm việc nhanh hơn và tốt hơn.\nLý Văn: Đúng rồi, nên làm việc khi cần làm việc, và nên thư giãn khi cần thư giãn.\nDương Đồng Lạc: Đúng vậy, bây giờ cuối tuần anh thường đến ngoại ô, thư giãn bản thân giữa núi non sông nước và phong cảnh đẹp.","audio_dialogue": "8-3.mp3","audio_vocab": "8-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "以前杨同乐总觉得自己年轻，就应该多学多干、积累经验。很多年轻人和他想法一样。但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响。现在越来越多的人认识到，跟一直加班相比，休息好了再工作，效率更高。因此，很多人开始做出改变，提醒自己减轻压力、多多放松。比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书。休息好了，再回去上班时，心情愉快，工作效率也更高。","pinyin": ""}],"translation_vn": "Trước đây Dương Đồng Lạc luôn nghĩ rằng mình còn trẻ, nên phải học nhiều làm nhiều, tích lũy kinh nghiệm. Rất nhiều người trẻ cũng có suy nghĩ giống anh. Nhưng vì công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất làm việc giảm xuống, sức khỏe cũng bị ảnh hưởng. Hiện nay ngày càng nhiều người nhận ra rằng, so với việc cứ liên tục tăng ca, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn. Vì vậy, nhiều người bắt đầu thay đổi, tự nhắc nhở bản thân giảm bớt áp lực, thư giãn nhiều hơn. Ví dụ, Dương Đồng Lạc vào cuối tuần thường cùng bạn bè đi chơi ở ngoại ô, thư giãn bản thân giữa cảnh sắc thiên nhiên tươi đẹp; hoặc ở nhà yên tĩnh đọc sách. Khi nghỉ ngơi đầy đủ rồi, lúc quay lại đi làm, tâm trạng vui vẻ, hiệu suất làm việc cũng cao hơn.","audio_dialogue": "8-5.mp3","audio_vocab": "8-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "一到周末，很多人都喜欢外出游玩。你一般去哪里呢？我生活在中国的首都——北京。在北京，周末的时候，有人会在市区公园走走，看看眼前的美景；有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化。北京交通很方便，所以我和家人更爱乘坐公交车去郊区，偶尔也会自己开车。郊区有山有水，还有很多农家乐，吃、玩、住都十分方便。在我看来，不管去哪里玩，实际上都是为了放松。也可以说，只要能放松，去哪儿都合适。","pinyin": ""}],"translation_vn": "Cứ đến cuối tuần là rất nhiều người thích ra ngoài đi chơi. Bạn thường đi đâu nhỉ? Tôi sống ở thủ đô của Trung Quốc — Bắc Kinh. Ở Bắc Kinh, vào cuối tuần, có người đi dạo ở công viên trong khu nội thành, ngắm nhìn cảnh đẹp trước mắt; có người thích đi tham quan các điểm du lịch nổi tiếng như Vạn Lý Trường Thành, Cố Cung, vừa thư giãn tâm trạng vừa có thể tìm hiểu lịch sử văn hóa. Giao thông ở Bắc Kinh rất thuận tiện, nên tôi và gia đình thích đi xe buýt ra ngoại ô hơn, thỉnh thoảng cũng tự lái xe. Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại, ăn, chơi, ở đều rất thuận tiện. Theo tôi, bất kể đi chơi ở đâu, thực chất đều là để thư giãn. Cũng có thể nói, chỉ cần có thể thư giãn được thì đi đâu cũng thích hợp.","audio_dialogue": "8-7.mp3","audio_vocab": "8-8.mp3"}]},{"id": 9,"title_cn": "遇见你，刚刚好","title_pinyin": "","title_vn": "Gặp em, thật vừa vặn","goals": ["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến tình yêu, tình bạn.","Có thể diễn đạt bằng lời nói hoặc văn viết về giá trị hay ý nghĩa của tình yêu, tình bạn.","Hiểu được quan niệm về tình yêu, tình bạn của người Trung Quốc."],"vocab": [{"hanzi": "祝","pinyin": "zhù","pos": "dgt.","vn": "chúc"},{"hanzi": "巧克力","pinyin": "qiǎokèlì","pos": "dt.","vn": "sô-cô-la"},{"hanzi": "感动","pinyin": "gǎndòng","pos": "tt./dgt.","vn": "cảm động; làm cảm động"},{"hanzi": "浪漫","pinyin": "làngmàn","pos": "tt.","vn": "lãng mạn"},{"hanzi": "幽默","pinyin": "yōumò","pos": "tt.","vn": "hài hước"},{"hanzi": "耐心","pinyin": "nàixīn","pos": "tt./dt.","vn": "kiên nhẫn; sự kiên nhẫn"},{"hanzi": "吸引","pinyin": "xīyǐn","pos": "dgt.","vn": "thu hút"},{"hanzi": "当时","pinyin": "dāngshí","pos": "dt.","vn": "lúc đó, khi đó"},{"hanzi": "错过","pinyin": "cuòguò","pos": "dgt.","vn": "bỏ lỡ"},{"hanzi": "幸运","pinyin": "xìngyùn","pos": "tt./dt.","vn": "may mắn"},{"hanzi": "幸福","pinyin": "xìngfú","pos": "tt./dt.","vn": "hạnh phúc"},{"hanzi": "尽管","pinyin": "jǐnguǎn","pos": "liên.","vn": "mặc dù"},{"hanzi": "性格","pinyin": "xìnggé","pos": "dt.","vn": "tính cách"},{"hanzi": "共同","pinyin": "gòngtóng","pos": "tt.","vn": "chung"},{"hanzi": "责任","pinyin": "zérèn","pos": "dt.","vn": "trách nhiệm"},{"hanzi": "相互","pinyin": "xiānghù","pos": "phó.","vn": "lẫn nhau, qua lại"},{"hanzi": "理解","pinyin": "lǐjiě","pos": "dgt.","vn": "hiểu, thấu hiểu"},{"hanzi": "支持","pinyin": "zhīchí","pos": "dgt.","vn": "ủng hộ"},{"hanzi": "印象","pinyin": "yìnxiàng","pos": "dt.","vn": "ấn tượng"},{"hanzi": "实在","pinyin": "shízài","pos": "tt./phó.","vn": "thật thà; thực ra"},{"hanzi": "阳光","pinyin": "yángguāng","pos": "tt./dt.","vn": "rạng rỡ; ánh nắng"},{"hanzi": "负责","pinyin": "fùzé","pos": "tt./dgt.","vn": "có trách nhiệm; phụ trách"},{"hanzi": "积极","pinyin": "jījí","pos": "tt.","vn": "tích cực"},{"hanzi": "此","pinyin": "cǐ","pos": "đt.","vn": "này"},{"hanzi": "从此","pinyin": "cóngcǐ","pos": "phó.","vn": "từ đó"},{"hanzi": "产生","pinyin": "chǎnshēng","pos": "dgt.","vn": "nảy sinh"},{"hanzi": "爱情","pinyin": "àiqíng","pos": "dt.","vn": "tình yêu"},{"hanzi": "间","pinyin": "jiān","pos": "dt.","vn": "khoảng giữa"},{"hanzi": "友情","pinyin": "yǒuqíng","pos": "dt.","vn": "tình bạn"},{"hanzi": "美好","pinyin": "měihǎo","pos": "tt.","vn": "tốt đẹp"},{"hanzi": "人生","pinyin": "rénshēng","pos": "dt.","vn": "cuộc đời, nhân sinh"},{"hanzi": "精彩","pinyin": "jīngcǎi","pos": "tt.","vn": "tuyệt vời, đặc sắc"},{"hanzi": "感情","pinyin": "gǎnqíng","pos": "dt.","vn": "tình cảm"},{"hanzi": "深","pinyin": "shēn","pos": "tt.","vn": "sâu đậm"},{"hanzi": "经营","pinyin": "jīngyíng","pos": "dgt.","vn": "vun đắp, quản lý"},{"hanzi": "对方","pinyin": "duìfāng","pos": "dt.","vn": "đối phương"},{"hanzi": "感受","pinyin": "gǎnshòu","pos": "dt./dgt.","vn": "cảm nhận"},{"hanzi": "尤其","pinyin": "yóuqí","pos": "phó.","vn": "đặc biệt là"},{"hanzi": "日子","pinyin": "rìzi","pos": "dt.","vn": "ngày tháng, cuộc sống"},{"hanzi": "从来","pinyin": "cónglái","pos": "phó.","vn": "từ trước đến nay"}],"grammar": [{"title": "紧缩复句\"不……也……\"","explanation_vn": "Câu phức rút gọn \"不……也……\" biểu thị rằng dù trong một điều kiện phủ định nào đó, kết quả phía sau vẫn chắc chắn xảy ra. Thường dùng trong khẩu ngữ.","examples": [{"cn": "我不说你也懂我在想什么。","pinyin": "","vn": "Em không nói mà anh vẫn hiểu em đang nghĩ gì."},{"cn": "他不复习也能考出好成绩。","pinyin": "","vn": "Cậu ấy không ôn bài vẫn thi được điểm cao."},{"cn": "我很清楚他为什么生气，不问我也知道。","pinyin": "","vn": "Tôi biết rất rõ tại sao anh ấy giận, không cần hỏi tôi cũng biết."}]},{"title": "转折复句\"尽管……，但是/可是……\"","explanation_vn": "Câu phức chuyển ý \"尽管……，但是/可是……\" biểu thị sự chuyển ý. \"尽管\" có nghĩa là \"mặc dù\", dùng để dẫn ra một tình huống nào đó, còn \"但是、可是\" dẫn ra tình huống hoặc kết quả trái ngược.","examples": [{"cn": "他们尽管性格不同，但是有很多共同爱好。","pinyin": "","vn": "Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung."},{"cn": "尽管时间紧张、压力很大，但是他们还是完成了任务。","pinyin": "","vn": "Dù thời gian gấp gáp, áp lực lớn, nhưng họ vẫn hoàn thành nhiệm vụ."},{"cn": "尽管她已经很累了，可是还是很耐心地给女儿读睡前故事。","pinyin": "","vn": "Dù cô ấy đã rất mệt, nhưng vẫn kiên nhẫn đọc truyện trước khi ngủ cho con gái."}]},{"title": "指示代词\"此\"","explanation_vn": "Đại từ chỉ định \"此\" biểu thị \"này, cái này\", thường dùng trong văn viết hoặc các trường hợp trang trọng.","examples": [{"cn": "此次出差，让两人熟悉了起来，从此成了好朋友。","pinyin": "","vn": "Chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt."},{"cn": "此人聪明、有能力，一定能顺利完成任务。","pinyin": "","vn": "Người này thông minh, có năng lực, nhất định sẽ hoàn thành nhiệm vụ thuận lợi."},{"cn": "此材料很重要，必须直接交给他。","pinyin": "","vn": "Tài liệu này rất quan trọng, phải trực tiếp đưa cho anh ấy."}]},{"title": "时间副词\"从来\"","explanation_vn": "Phó từ chỉ thời gian \"从来\" chỉ việc gì đó luôn như vậy từ trước đến nay. Thường dùng trong câu phủ định, đôi khi cũng dùng trong câu khẳng định.","examples": [{"cn": "爱，从来都是相互尊重、理解与支持，不是吗？","pinyin": "","vn": "Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?"},{"cn": "我从来没见过这个颜色的花，它叫什么名字啊？","pinyin": "","vn": "Tôi chưa từng thấy bông hoa màu này bao giờ, nó tên là gì vậy?"},{"cn": "我从来不喜欢一个人旅游，每次都要和家人或朋友一起去。","pinyin": "","vn": "Tôi chưa bao giờ thích đi du lịch một mình, lần nào cũng phải đi cùng gia đình hoặc bạn bè."}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "李文","cn": "家月，给你的，祝你生日快乐！","pinyin": ""},{"speaker": "白家月","cn": "啊，好漂亮的花！还有巧克力！你怎么知道我喜欢这个巧克力？","pinyin": ""},{"speaker": "李文","cn": "上次咱们去超市，看你拿起来看了看又放下了，我就记住了。","pinyin": ""},{"speaker": "白家月","cn": "好感动！我不说你也懂我在想什么，你真是细心又浪漫。其实刚认识不久，你的幽默与耐心就很吸引我，不过我当时也只把你当普通朋友。如果你没有一直找我聊天儿，我们可能就错过了。","pinyin": ""},{"speaker": "李文","cn": "我终于遇见了对的人，哪能错过呢？","pinyin": ""},{"speaker": "白家月","cn": "遇见你，我也觉得很幸运。","pinyin": ""}],"translation_vn": "Lý Văn: Gia Nguyệt, tặng em này, chúc em sinh nhật vui vẻ!\nBạch Gia Nguyệt: A, hoa đẹp quá! Còn có cả sô-cô-la nữa! Sao anh biết em thích loại sô-cô-la này?\nLý Văn: Lần trước mình đi siêu thị, anh thấy em cầm lên xem rồi lại đặt xuống, nên anh nhớ luôn.\nBạch Gia Nguyệt: Cảm động quá! Em không nói mà anh vẫn hiểu em đang nghĩ gì, anh đúng là người tinh tế lại lãng mạn. Thật ra mới quen nhau không lâu, sự hài hước và kiên nhẫn của anh đã rất thu hút em rồi, nhưng lúc đó em cũng chỉ coi anh là bạn bình thường thôi. Nếu anh không liên tục tìm em trò chuyện, có lẽ chúng ta đã bỏ lỡ nhau rồi.\nLý Văn: Cuối cùng anh cũng gặp được đúng người, sao có thể bỏ lỡ được chứ?\nBạch Gia Nguyệt: Gặp được anh, em cũng thấy mình thật may mắn.","audio_dialogue": "9-1.mp3","audio_vocab": "9-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一雪","cn": "看到一飞和同乐结婚后这么幸福，我这个介绍人也特别开心。","pinyin": ""},{"speaker": "刘明","cn": "是啊，同乐是你的好朋友，一飞是你妹妹，你都很了解。","pinyin": ""},{"speaker": "王一雪","cn": "嗯，他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。","pinyin": ""},{"speaker": "刘明","cn": "是的，一飞也算在对的时间遇到了对的人。后边的路还很长，希望他们能一直相互理解、相互支持。","pinyin": ""},{"speaker": "王一雪","cn": "我了解同乐，更了解一飞，相信他们会一直走下去的。","pinyin": ""},{"speaker": "刘明","cn": "祝他们越来越幸福。","pinyin": ""}],"translation_vn": "Vương Nhất Tuyết: Thấy Nhất Phi và Đồng Lạc kết hôn hạnh phúc như vậy, mình là người mai mối cũng thấy đặc biệt vui.\nLưu Minh: Đúng vậy, Đồng Lạc là bạn thân của em, Nhất Phi là em gái em, em hiểu rõ cả hai người.\nVương Nhất Tuyết: Ừm, dù hai người tính cách khác nhau, nhưng có rất nhiều sở thích chung. Đặc biệt Đồng Lạc là người tốt, tính cách cũng tốt, rất có trách nhiệm.\nLưu Minh: Đúng vậy, Nhất Phi cũng coi như đã gặp đúng người vào đúng thời điểm. Con đường phía trước còn dài, hy vọng họ sẽ luôn thấu hiểu và ủng hộ lẫn nhau.\nVương Nhất Tuyết: Em hiểu Đồng Lạc, lại càng hiểu Nhất Phi hơn, tin rằng họ sẽ đi cùng nhau đến cuối con đường.\nLưu Minh: Chúc họ ngày càng hạnh phúc.","audio_dialogue": "9-3.mp3","audio_vocab": "9-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "王一雪比杨同乐更早进入公司。杨同乐刚来不久，王一雪对他印象就非常好：人很实在，性格阳光，工作负责，表现积极……后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。一次聊天儿时，王一雪了解到杨同乐还没女朋友，正好自己的妹妹王一飞也没有男朋友，于是王一雪就把王一飞介绍给了他。杨同乐和王一飞认识后，很聊得来，两人之间慢慢产生了爱情，最后成了夫妻。杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。","pinyin": ""}],"translation_vn": "Vương Nhất Tuyết vào công ty sớm hơn Dương Đồng Lạc. Dương Đồng Lạc mới đến chưa lâu, Vương Nhất Tuyết đã có ấn tượng rất tốt về anh: con người thật thà, tính cách rạng rỡ, làm việc có trách nhiệm, thể hiện tích cực... Sau đó hai người cùng đi công tác một lần, chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt của nhau. Trong một lần trò chuyện, Vương Nhất Tuyết biết được Dương Đồng Lạc vẫn chưa có bạn gái, đúng lúc em gái mình là Vương Nhất Phi cũng chưa có bạn trai, thế là Vương Nhất Tuyết liền giới thiệu Nhất Phi cho anh. Sau khi Dương Đồng Lạc và Vương Nhất Phi quen biết nhau, hai người rất hợp chuyện, tình cảm giữa họ dần dần nảy sinh, cuối cùng trở thành vợ chồng. Dương Đồng Lạc nói rằng mình thật may mắn, chính tình bạn đồng nghiệp này với Vương Nhất Tuyết đã mang đến cho anh một tình yêu tốt đẹp.","audio_dialogue": "9-5.mp3","audio_vocab": "9-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "李文在校园里遇见白家月，从此，他们的人生变得更加精彩；王一飞和杨同乐通过王一雪介绍认识后，感情越来越深，最后两人幸福地走到了一起。在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。遇见你，刚刚好。不过美好的遇见只是爱的开始，爱更需要经营。在一段感情中，两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。爱，从来都是相互尊重、理解与支持，不是吗？","pinyin": ""}],"translation_vn": "Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường, từ đó, cuộc sống của họ trở nên rực rỡ hơn; Vương Nhất Phi và Dương Đồng Lạc quen nhau qua sự giới thiệu của Vương Nhất Tuyết, tình cảm ngày càng sâu đậm, cuối cùng hai người đã hạnh phúc đến với nhau. Theo tôi, cách thức gặp được tình yêu không quan trọng, điều quan trọng là đã gặp đúng người vào đúng thời điểm. Gặp em, thật vừa vặn. Nhưng cuộc gặp gỡ tốt đẹp chỉ là khởi đầu của tình yêu, tình yêu còn cần được vun đắp nhiều hơn nữa. Trong một mối quan hệ, hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn, càng cần cùng nhau vun đắp tổ ấm, để cuộc sống ngày càng tốt đẹp hơn. Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?","audio_dialogue": "9-7.mp3","audio_vocab": "9-8.mp3"}]},{"id": 10,"title_cn": "南方不懂北方的冷","title_pinyin": "","title_vn": "Người miền Nam không hiểu cái lạnh miền Bắc","goals": ["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến mối quan hệ giữa khí hậu với môi trường, cuộc sống.","Có thể diễn đạt bằng lời nói hoặc văn viết về tầm quan trọng và cách thực hiện cụ thể của việc bảo vệ môi trường.","Hiểu được sự khác biệt về khí hậu, đời sống xã hội,... giữa miền Nam và miền Bắc Trung Quốc."],"vocab": [{"hanzi": "小伙子","pinyin": "xiǎohuǒzi","pos": "dt.","vn": "chàng trai, anh chàng"},{"hanzi": "气温","pinyin": "qìwēn","pos": "dt.","vn": "nhiệt độ không khí"},{"hanzi": "零下","pinyin": "líng xià","pos": "","vn": "dưới 0 độ, âm độ"},{"hanzi": "度","pinyin": "dù","pos": "lượng.","vn": "độ"},{"hanzi": "冻","pinyin": "dòng","pos": "dgt.","vn": "lạnh cóng, đóng băng"},{"hanzi": "后悔","pinyin": "hòuhuǐ","pos": "dgt.","vn": "hối hận"},{"hanzi": "就是","pinyin": "jiùshì","pos": "phó.","vn": "đúng vậy, chính là"},{"hanzi": "温度","pinyin": "wēndù","pos": "dt.","vn": "nhiệt độ"},{"hanzi": "差别","pinyin": "chābié","pos": "dt.","vn": "sự khác biệt"},{"hanzi": "厚","pinyin": "hòu","pos": "tt.","vn": "dày"},{"hanzi": "广州","pinyin": "Guǎngzhōu","pos": "danh từ riêng","vn": "Quảng Châu"},{"hanzi": "哈尔滨","pinyin": "Hā'ěrbīn","pos": "danh từ riêng","vn": "Cáp Nhĩ Tân"},{"hanzi": "寒假","pinyin": "hánjià","pos": "dt.","vn": "kỳ nghỉ đông"},{"hanzi": "暖和","pinyin": "nuǎnhuo","pos": "tt./dgt.","vn": "ấm áp; trở nên ấm áp"},{"hanzi": "低于","pinyin": "dīyú","pos": "dgt.","vn": "thấp hơn"},{"hanzi": "摄氏度","pinyin": "shèshìdù","pos": "lượng.","vn": "độ C"},{"hanzi": "受不了","pinyin": "shòubuliǎo","pos": "dgt.","vn": "không chịu nổi"},{"hanzi": "举办","pinyin": "jǔbàn","pos": "dgt.","vn": "tổ chức"},{"hanzi": "各种","pinyin": "gèzhǒng","pos": "đt.","vn": "các loại, mọi loại"},{"hanzi": "植物","pinyin": "zhíwù","pos": "dt.","vn": "thực vật"},{"hanzi": "公里","pinyin": "gōnglǐ","pos": "lượng.","vn": "ki-lô-mét"},{"hanzi": "气候","pinyin": "qìhòu","pos": "dt.","vn": "khí hậu"},{"hanzi": "而","pinyin": "ér","pos": "liên.","vn": "mà, nhưng, và"},{"hanzi": "此外","pinyin": "cǐwài","pos": "liên.","vn": "ngoài ra"},{"hanzi": "方言","pinyin": "fāngyán","pos": "dt.","vn": "phương ngữ, tiếng địa phương"},{"hanzi": "普通话","pinyin": "pǔtōnghuà","pos": "dt.","vn": "tiếng phổ thông (Trung Quốc)"},{"hanzi": "较","pinyin": "jiào","pos": "phó.","vn": "tương đối, khá"},{"hanzi": "使用","pinyin": "shǐyòng","pos": "dgt.","vn": "sử dụng"},{"hanzi": "引起","pinyin": "yǐnqǐ","pos": "dgt.","vn": "gây ra"},{"hanzi": "误会","pinyin": "wùhuì","pos": "dt./dgt.","vn": "hiểu lầm"},{"hanzi": "亲爱","pinyin": "qīn'ài","pos": "tt.","vn": "thân mến"},{"hanzi": "再次","pinyin": "zàicì","pos": "phó.","vn": "một lần nữa"},{"hanzi": "开展","pinyin": "kāizhǎn","pos": "dgt.","vn": "triển khai"},{"hanzi": "绿色","pinyin": "lǜsè","pos": "tt.","vn": "xanh, thân thiện với môi trường"},{"hanzi": "环保","pinyin": "huánbǎo","pos": "dt./tt.","vn": "bảo vệ môi trường"},{"hanzi": "拒绝","pinyin": "jùjué","pos": "dgt.","vn": "từ chối"},{"hanzi": "浪费","pinyin": "làngfèi","pos": "dgt.","vn": "lãng phí"},{"hanzi": "节约","pinyin": "jiéyuē","pos": "dgt.","vn": "tiết kiệm"},{"hanzi": "资源","pinyin": "zīyuán","pos": "dt.","vn": "tài nguyên"},{"hanzi": "光","pinyin": "guāng","pos": "tt.","vn": "hết sạch"},{"hanzi": "垃圾","pinyin": "lājī","pos": "dt.","vn": "rác"},{"hanzi": "分类","pinyin": "fēnlèi","pos": "dgt.","vn": "phân loại"},{"hanzi": "日常","pinyin": "rìcháng","pos": "tt.","vn": "thường ngày, hàng ngày"}],"grammar": [{"title": "固定格式\"说什么/怎么（着）也得×\"","explanation_vn": "Cấu trúc cố định \"说什么/怎么（着）也得×\" biểu thị sự cần thiết hoặc quyết tâm bắt buộc phải làm gì đó, thường dùng trong khẩu ngữ.","examples": [{"cn": "更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin": "","vn": "Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."},{"cn": "假期还有两天就结束了，我明天说什么也得把作业做完了。","pinyin": "","vn": "Kỳ nghỉ còn hai ngày nữa là kết thúc, ngày mai dù thế nào tôi cũng phải làm xong bài tập."},{"cn": "我很后悔上次没参加这个活动，这次怎么着也得去。","pinyin": "","vn": "Tôi rất hối hận vì lần trước không tham gia hoạt động này, lần này dù thế nào cũng phải đi."}]},{"title": "固定短语\"有的是\"","explanation_vn": "Cụm từ cố định \"有的是\" thường dùng trong khẩu ngữ, biểu thị có rất nhiều, nhấn mạnh số lượng dồi dào.","examples": [{"cn": "没问题，受得了，我有的是厚衣服。","pinyin": "","vn": "Không vấn đề gì, chịu được, tôi có thừa quần áo dày."},{"cn": "过年时，家里有的是好吃的、好喝的，孩子们特别开心。","pinyin": "","vn": "Dịp Tết, trong nhà có đầy đồ ăn ngon, đồ uống ngon, bọn trẻ đặc biệt vui."},{"cn": "这个市场特别大，有的是水果和菜，你想买什么菜都能买到。","pinyin": "","vn": "Khu chợ này rất lớn, có đủ loại hoa quả và rau, bạn muốn mua rau gì cũng mua được."}]},{"title": "连词\"而\"","explanation_vn": "Liên từ \"而\" nối động từ, tính từ hoặc cụm từ, vế câu, có nhiều nghĩa khác nhau, ở đây giới thiệu ba cách dùng: (1) biểu thị sự chuyển ý, \"而\" nối hai thành phần có ý nghĩa trái ngược nhau; (2) biểu thị sự tiếp nối về mặt ý nghĩa; (3) biểu thị quan hệ nhân quả trước sau về mặt sự lý.","examples": [{"cn": "广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","pinyin": "","vn": "Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc."},{"cn": "在这个紧张而兴奋的日子里，我们都走出教室，为运动员们加油。","pinyin": "","vn": "Trong những ngày căng thẳng mà phấn khích này, chúng tôi đều ra khỏi lớp học để cổ vũ cho các vận động viên."},{"cn": "冬天，这个城市因为天气暖和而吸引了很多游客。","pinyin": "","vn": "Vào mùa đông, thành phố này vì thời tiết ấm áp nên thu hút rất nhiều du khách."}]},{"title": "频率副词\"再次\"","explanation_vn": "Phó từ tần suất \"再次\" đứng trước động từ, biểu thị lần thứ hai, thêm một lần nữa.","examples": [{"cn": "今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动。","pinyin": "","vn": "Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\"."},{"cn": "我去年冬天去过一次哈尔滨，很喜欢那里的雪；今年冬天，我计划再次去哈尔滨看雪。","pinyin": "","vn": "Mùa đông năm ngoái tôi từng đến Cáp Nhĩ Tân một lần, rất thích tuyết ở đó; mùa đông năm nay, tôi dự định đi Cáp Nhĩ Tân ngắm tuyết một lần nữa."},{"cn": "再次感谢您的支持与关心！","pinyin": "","vn": "Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!"}]}],"texts": [{"label": "Bài khóa 1","type": "dialogue","lines": [{"speaker": "刘明","cn": "你看，这个小伙子从广州去哈尔滨出差，没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。","pinyin": ""},{"speaker": "王一雪","cn": "他一定后悔自己穿少了吧？","pinyin": ""},{"speaker": "刘明","cn": "是啊，这就叫南方不懂北方的冷。","pinyin": ""},{"speaker": "王一雪","cn": "就是呢，冬天北方和南方的温度差别还是很大的。","pinyin": ""},{"speaker": "刘明","cn": "所以冬天来北方，尤其是东北，一定要提前查好目的地的天气，看看下不下雪，气温怎么样。","pinyin": ""},{"speaker": "王一雪","cn": "对。更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin": ""}],"translation_vn": "Lưu Minh: Em xem này, anh chàng này từ Quảng Châu đi công tác đến Cáp Nhĩ Tân, không ngờ nhiệt độ ở Cáp Nhĩ Tân hạ xuống âm hai mươi mấy độ, khiến anh ta lạnh cóng luôn.\nVương Nhất Tuyết: Chắc anh ta hối hận vì mặc ít đồ quá nhỉ?\nLưu Minh: Đúng vậy, đây gọi là người miền Nam không hiểu được cái lạnh của miền Bắc.\nVương Nhất Tuyết: Đúng thế, mùa đông sự chênh lệch nhiệt độ giữa miền Bắc và miền Nam vẫn rất lớn.\nLưu Minh: Vì vậy mùa đông đến miền Bắc, đặc biệt là vùng Đông Bắc, nhất định phải tra trước thời tiết nơi đến, xem có tuyết không, nhiệt độ thế nào.\nVương Nhất Tuyết: Đúng vậy. Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút.","audio_dialogue": "10-1.mp3","audio_vocab": "10-2.mp3"},{"label": "Bài khóa 2","type": "dialogue","lines": [{"speaker": "王一飞","cn": "寒假你们打算做什么呢？","pinyin": ""},{"speaker": "陈天中","cn": "我们刚刚还说呢，家月春节时要去广州，我计划去哈尔滨。","pinyin": ""},{"speaker": "王一飞","cn": "那时候广州暖和，但哈尔滨特别冷，气温一般都低于零下十摄氏度甚至零下二十摄氏度，这么低的温度你受不了吧？","pinyin": ""},{"speaker": "陈天中","cn": "没问题，受得了，我有的是厚衣服。我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。","pinyin": ""},{"speaker": "白家月","cn": "我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。","pinyin": ""},{"speaker": "王一飞","cn": "真不错！听你们这么一说，我也想外出旅游了。","pinyin": ""}],"translation_vn": "Vương Nhất Phi: Kỳ nghỉ đông các bạn định làm gì vậy?\nTrần Thiên Trung: Bọn mình vừa mới nói đấy, Gia Nguyệt Tết sẽ đi Quảng Châu, mình thì định đi Cáp Nhĩ Tân.\nVương Nhất Phi: Lúc đó Quảng Châu ấm áp, nhưng Cáp Nhĩ Tân lại rất lạnh, nhiệt độ thường thấp hơn âm mười độ C thậm chí âm hai mươi độ C, nhiệt độ thấp như vậy cậu chịu được không?\nTrần Thiên Trung: Không vấn đề gì, chịu được, mình có thừa quần áo dày mà. Mình đi Cáp Nhĩ Tân chủ yếu là muốn xem tuyết, nghe nói Tết ở đó sẽ tổ chức rất nhiều hoạt động.\nBạch Gia Nguyệt: Mình muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa mình thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng, trong đó có đủ loại thực vật.\nVương Nhất Phi: Hay thật đấy! Nghe các bạn nói vậy, mình cũng muốn đi du lịch rồi.","audio_dialogue": "10-3.mp3","audio_vocab": "10-4.mp3"},{"label": "Bài khóa 3","type": "passage","lines": [{"speaker": "","cn": "广州和哈尔滨，一个在南方，一个在北方，两个城市之间的距离有三千多公里，气候也大不相同。广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。广州四季开满鲜花，所以又叫\"花城\"；哈尔滨冬天冰雪多，所以也叫\"冰城\"。此外，两地的方言也不一样。哈尔滨方言和普通话听起来比较像，而广州方言和普通话差别较大。如果广州人和哈尔滨人都只使用自己的方言，那么交流就很困难，甚至还可能引起误会。其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。","pinyin": ""}],"translation_vn": "Quảng Châu và Cáp Nhĩ Tân, một ở miền Nam, một ở miền Bắc, khoảng cách giữa hai thành phố hơn ba nghìn ki-lô-mét, khí hậu cũng rất khác nhau. Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc. Quảng Châu bốn mùa hoa nở rộ, nên còn được gọi là \"thành phố hoa\"; mùa đông ở Cáp Nhĩ Tân nhiều băng tuyết, nên cũng được gọi là \"thành phố băng\". Ngoài ra, phương ngữ của hai nơi cũng không giống nhau. Phương ngữ Cáp Nhĩ Tân nghe khá giống tiếng phổ thông, còn phương ngữ Quảng Châu lại khác biệt khá lớn so với tiếng phổ thông. Nếu người Quảng Châu và người Cáp Nhĩ Tân đều chỉ dùng phương ngữ của mình, thì việc giao tiếp sẽ rất khó khăn, thậm chí còn có thể gây hiểu lầm. Thực ra, rất nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy, để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông.","audio_dialogue": "10-5.mp3","audio_vocab": "10-6.mp3"},{"label": "Bài khóa 4","type": "passage","lines": [{"speaker": "","cn": "亲爱的同学们：今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动，希望同学们做到：一、绿色出行。绿色一小步，环保一大步。根据距离选择绿色交通方式。距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。二、拒绝浪费。节约资源，坚持一水多用、人走灯关、餐餐都\"光盘\"。三、垃圾分类。积极参加校园、小区环保活动，学习垃圾分类知识，从小事做起，做好垃圾分类。保护环境是每一个人的责任。同学们，让我们共同努力，让绿色生活成为我们的日常习惯！校学生会 2026年6月5日","pinyin": ""}],"translation_vn": "Các bạn học sinh thân mến: Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\", hy vọng các bạn làm được những điều sau: Một, Di chuyển xanh. Một bước nhỏ xanh, một bước lớn bảo vệ môi trường. Hãy chọn phương thức di chuyển xanh tùy theo khoảng cách. Khi khoảng cách gần có thể đi bộ hoặc đi xe đạp, khi khoảng cách xa nên đi xe buýt hoặc tàu điện ngầm nhiều hơn. Hai, Nói không với lãng phí. Tiết kiệm tài nguyên, kiên trì dùng nước nhiều lần, ra khỏi phòng tắt đèn, mỗi bữa ăn đều \"sạch đĩa\". Ba, Phân loại rác. Tích cực tham gia các hoạt động bảo vệ môi trường ở trường học, khu dân cư, học kiến thức phân loại rác, bắt đầu từ những việc nhỏ, làm tốt việc phân loại rác. Bảo vệ môi trường là trách nhiệm của mỗi người. Các bạn ơi, hãy cùng nhau nỗ lực, để lối sống xanh trở thành thói quen hàng ngày của chúng ta! Hội Học sinh Nhà trường, Ngày 5 tháng 6 năm 2026","audio_dialogue": "10-7.mp3","audio_vocab": "10-8.mp3"}]}],"pos_table": [{"pos_cn": "名词","pos_vn": "Danh từ","abbr": "dt."},{"pos_cn": "动词","pos_vn": "Động từ","abbr": "dgt."},{"pos_cn": "形容词","pos_vn": "Tính từ","abbr": "tt."},{"pos_cn": "代词","pos_vn": "Đại từ","abbr": "đt."},{"pos_cn": "副词","pos_vn": "Phó từ","abbr": "phó."},{"pos_cn": "介词","pos_vn": "Giới từ","abbr": "giới."},{"pos_cn": "连词","pos_vn": "Liên từ","abbr": "liên."},{"pos_cn": "助词","pos_vn": "Trợ từ","abbr": "trợ."},{"pos_cn": "数词","pos_vn": "Từ chỉ số đếm","abbr": "số."},{"pos_cn": "量词","pos_vn": "Lượng từ","abbr": "lượng."},{"pos_cn": "数量词","pos_vn": "Từ chỉ số lượng","abbr": "sl."},{"pos_cn": "叹词","pos_vn": "Từ cảm thán","abbr": "ct."},{"pos_cn": "拟声词","pos_vn": "Từ tượng thanh","abbr": "tượng."},{"pos_cn": "能愿动词","pos_vn": "Động từ năng nguyện","abbr": "đtnn."},{"pos_cn": "前缀","pos_vn": "Tiền tố","abbr": "ttố."},{"pos_cn": "后缀","pos_vn": "Hậu tố","abbr": "htố."}]};
